                                                        <MessageSquare className="w-3 h-3 text-emerald-200 shrink-0" />
                                                        <span className="text-[9px] font-medium text-emerald-400/80 italic max-w-[150px] whitespace-normal text-right">{entry.actualRemark}</span>
                                                      </div>
                                                    )}
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className={`text-sm font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                                        {(eff || 0).toFixed(0)}%
                                                    </span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-[11px] font-bold text-slate-400 uppercase tracking-tighter font-mono">{entry.batchNo || '-'}</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-base font-black text-slate-800 dark:text-white font-mono">{Number(entry.manpower || 0)}</span>
                                                </td>
                                                {hasPermission(['admin', 'manager', 'planner']) && (
                                                  <td className="px-8 py-5">
                                                      <div className="flex items-center justify-center gap-2">
