import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { ProductionEntry, Category, ProcessType, UnitType, ProductionStatus } from '../../types';
import { X, Loader2, AlertTriangle, Palmtree, MessageSquare } from 'lucide-react';
import { getTodayISO, getDbTimestamp } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState<UnitType>('KG');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');
  const [planRemark, setPlanRemark] = useState('');
  const [actualRemark, setActualRemark] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => {
    const inputDate = (date || '').trim().split(' ')[0];
    return offDays.find(od => (od.date || '').trim().split(' ')[0] === inputDate);
  }, [date, offDays]);

  const availableProcesses = useMemo(() => {
    if (['Toothpaste', 'Rocksalt', 'Cosmetic'].includes(category)) {
      return PROCESSES.filter(p => p !== 'Encapsulation');
    }
    return [...PROCESSES];
  }, [category]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (!availableProcesses.includes(process)) {
      setProcess(availableProcesses[0]);
    }
  }, [category, availableProcesses, process]);

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().split(' ')[0]);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setUnit(editEntry.unit || 'KG');

      if (editEntry.actualQuantity > 0) {
        setTab('Actual');
        setQuantity(editEntry.actualQuantity.toString());
      } else {
        setTab('Plan');
        setQuantity(editEntry.planQuantity.toString());
      }

      setManpower(editEntry.manpower ? Number(editEntry.manpower).toString() : '0');
      setBatchNo(editEntry.batchNo || '');
      setPlanRemark(editEntry.planRemark || '');
      setActualRemark(editEntry.actualRemark || '');
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const normalizedInputDate = (date || '').trim().split(' ')[0];
        const relevant = all.filter(p => (p.date || '').trim().split(' ')[0] === normalizedInputDate);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  useEffect(() => {
    if (tab === 'Actual' && selectedPlanId && !editEntry) {
        const target = plans.find(p => p.id === selectedPlanId);
        if (target) {
            setUnit(target.unit || 'KG');
        }
    }
  }, [selectedPlanId, tab, plans, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    const normalizedDate = (date || '').trim().split(' ')[0];

    if (!editEntry && currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `ENTRY RESTRICTED: Today is ${currentOffDay.description}`, type: 'info' } 
        }));
        setIsSubmitting(false);
        return;
    }

    const currentData = StorageService.getProductionData();
    // Rule: Plan only = In Progress, Actual submitted = Completed
    const determinedStatus: ProductionStatus = tab === 'Actual' ? 'Completed' : 'In Progress';

    try {
        if (editEntry) {
            const updated = currentData.map(p => {
                if (p.id === editEntry.id) {
                    const newQty = parseInt(quantity || '0');
                    return { 
                        ...p, 
                        date: normalizedDate, 
                        category, process, productName, unit,
                        planQuantity: tab === 'Plan' ? newQty : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? newQty : p.actualQuantity,
                        batchNo, manpower: parseFloat(manpower || '0'),
                        planRemark,
                        actualRemark,
                        status: tab === 'Actual' && newQty > 0 ? 'Completed' : p.status,
                        lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                    };
                }
                return p;
            });

            StorageService.saveProductionData(updated);
            StorageService.addLog({
              userId: user!.id,
              userName: user!.name,
              action: 'EDIT_RECORD',
              details: `Updated record ${productName} (Status: ${determinedStatus})`
            });
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date: normalizedDate, 
                    category, process, productName, unit,
                    planQuantity: parseInt(quantity || '0'), actualQuantity: 0,
                    planRemark,
                    actualRemark: '',
                    status: 'In Progress',
                    lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'CREATE_PLAN',
                  details: `Planned ${newEntry.planQuantity} ${newEntry.unit} for ${newEntry.productName}`
                });
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const updated = currentData.map(p => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity || '0'), 
                            unit, 
                            batchNo, 
                            manpower: parseFloat(manpower || '0'),
                            actualRemark,
                            status: 'Completed',
                            lastUpdatedBy: user!.id, 
                            updatedAt: getDbTimestamp()
                        };
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'RECORD_ACTUAL',
                  details: `Recorded actual output for ${productName} (Marked as Completed)`
                });
            }
        }

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: determinedStatus === 'Completed' ? 'PRODUCTION COMPLETED & SAVED' : 'PRODUCTION PLAN SAVED', type: 'success' } 
        }));

        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: err.message || 'Operation failed', type: 'info' } 
        }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative max-h-[90vh] flex flex-col">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-[60] flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Uploading to Cloud...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700 shrink-0">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        1. Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-500 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        2. Record Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 flex overflow-hidden">
                <button onClick={() => setTab('Plan')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600 bg-indigo-50/10' : 'border-transparent text-slate-400'}`}>
                    Plan Details
                </button>
                <button onClick={() => setTab('Actual')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Actual' ? 'border-emerald-500 text-emerald-600 bg-emerald-50/10' : 'border-transparent text-slate-400'}`}>
                    Actual Results
                </button>
              </div>
            )}
        </div>

        <div className="p-6 relative overflow-y-auto custom-scrollbar flex-1">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors z-20"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {currentOffDay && (
                      <div className="mt-3 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-300 dark:border-amber-700 rounded-xl flex items-center gap-3 animate-pulse shadow-sm">
                        <div className="p-2 bg-amber-500 text-white rounded-lg shadow-md">
                          <Palmtree className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className="text-[10px] font-black text-amber-700 dark:text-amber-400 uppercase tracking-widest leading-none mb-1">Public Holiday</p>
                          <p className="text-xs font-black text-slate-900 dark:text-amber-50">{currentOffDay.description || 'OFF DAY'}</p>
                        </div>
                      </div>
                    )}
                </div>

                {tab === 'Plan' ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {availableProcesses.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input 
                              type="text" 
                              required 
                              value={productName} 
                              onChange={e => setProductName(e.target.value.toUpperCase())} 
                              className={inputClasses} 
                              placeholder="Enter product name..." 
                            />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="flex-1">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Target Plan Qty</label>
                                <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                            </div>
                            <div className="w-24">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                    {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5">
                              <MessageSquare className="w-3 h-3" /> Plan Remark
                            </label>
                            <textarea 
                                value={planRemark} 
                                onChange={e => setPlanRemark(e.target.value.toUpperCase())} 
                                className={`${inputClasses} h-20 resize-none font-medium text-xs`}
                                placeholder="ADD PLANNING NOTES..."
                            />
                        </div>
                    </>
                ) : (
                    <>
                        {!editEntry && (
                          <div className="mb-4">
                               <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Pending Job</label>
                               {plans.length === 0 ? <div className="text-xs text-slate-400 italic text-center p-6 border-2 border-dashed rounded-xl">No plans found for this date.</div> : (
                                   <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                                       {plans.map(p => (
                                           <div key={p.id} onClick={() => { setSelectedPlanId(p.id); setProductName(p.productName); setProcess(p.process); setCategory(p.category); }}
                                              className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                              <div className="font-black text-sm">{p.productName}</div>
                                              <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-emerald-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity} {p.unit || 'KG'}</div>
                                           </div>
                                       ))}
                                   </div>
                               )}
                          </div>
                        )}
                        {(selectedPlanId || editEntry) && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="flex-1">
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Result Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div className="w-24">
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                        <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                            {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                        </select>
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                  <div className="col-span-2">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                  </div>
                                  <div className="col-span-2">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower Used</label>
                                    <input type="number" required step="any" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                  </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5">
                                      <MessageSquare className="w-3 h-3" /> Actual Remark
                                    </label>
                                    <textarea 
                                        value={actualRemark} 
                                        onChange={e => setActualRemark(e.target.value.toUpperCase())} 
                                        className={`${inputClasses} h-20 resize-none font-medium text-xs`}
                                        placeholder="ADD ACTUAL NOTES..."
                                    />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button 
                    type="submit" 
                    disabled={isSubmitting || (!editEntry && !!currentOffDay)} 
                    className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-4 shadow-xl transition hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed ${
                        !!currentOffDay && !editEntry ? 'bg-amber-600' : 
                        tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600 shadow-indigo-500/10' : 
                        'bg-emerald-600 shadow-emerald-500/10'
                    }`}
                >
                    {isSubmitting ? 'Syncing...' : (!!currentOffDay && !editEntry ? 'Holiday Entry Locked' : (tab === 'Actual' ? 'Submit & Mark Completed' : 'Save Plan Entry'))}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import { User, ProductionEntry, OffDay, ActivityLog, UnitType, ProductionStatus } from '../types';
import { INITIAL_USERS, INITIAL_OFF_DAYS, generateSeedProductionData, UNITS } from '../constants';
import { GoogleSheetsService } from './googleSheetsService';
import { getDbTimestamp } from '../utils/dateUtils';

const KEYS = {
  USERS: 'halagel_users',
  PRODUCTION: 'halagel_production',
  OFF_DAYS: 'halagel_off_days',
  LOGS: 'halagel_activity_logs',
  CURRENT_USER: 'halagel_current_user_session',
};

// Helper to normalize units safely
const normalizeUnit = (u: any): UnitType => {
  if (u === undefined || u === null || u === '') return 'KG';
  const upper = String(u).trim().toUpperCase();
  const validUnits = UNITS as unknown as string[];
  return validUnits.includes(upper) ? (upper as UnitType) : 'KG';
};

// Normalizer for Production Entries - Ensures NO property is ever undefined/null
const normalizeProduction = (data: any): ProductionEntry => {
  if (!data) return {} as ProductionEntry;

  let entry: Partial<ProductionEntry> = {};

  // If data comes from Google Sheets as an array
  if (Array.isArray(data)) {
    const actualQty = Number(data[6] || 0);
    entry = {
      id: String(data[0] || Date.now()),
      date: String(data[1] || '').split(' ')[0],
      category: String(data[2] || 'Healthcare') as any,
      process: String(data[3] || 'Mixing') as any,
      productName: String(data[4] || 'Unknown'),
      planQuantity: Number(data[5] || 0),
      actualQuantity: actualQty,
      unit: normalizeUnit(data[7]), // Column H
      batchNo: String(data[8] || ''),
      manpower: Number(data[9] || 0),
      lastUpdatedBy: String(data[10] || ''),
      updatedAt: String(data[11] || getDbTimestamp()),
      remark: String(data[12] || ''),
      planRemark: String(data[13] || ''),
      actualRemark: String(data[14] || ''),
      // Rule: If actual submitted, it's completed. Otherwise in progress.
      status: (data[15] as ProductionStatus) || (actualQty > 0 ? 'Completed' : 'In Progress')
    };
  } else {
    // If data comes from LocalStorage as an object
    const actualQty = Number(data.actualQuantity || 0);
    entry = {
      ...data,
      id: String(data.id || Date.now()),
      date: String(data.date || '').split(' ')[0],
      productName: String(data.productName || 'Unknown'),
      planQuantity: Number(data.planQuantity || 0),
      actualQuantity: actualQty,
      unit: normalizeUnit(data.unit),
      manpower: Number(data.manpower || 0),
      batchNo: String(data.batchNo || ''),
      remark: String(data.remark || ''),
      planRemark: String(data.planRemark || ''),
      actualRemark: String(data.actualRemark || ''),
      process: String(data.process || 'Mixing') as any,
      category: String(data.category || 'Healthcare') as any,
      // Rule: If actual submitted, it's completed. Otherwise in progress.
      status: actualQty > 0 ? 'Completed' : 'In Progress',
      updatedAt: String(data.updatedAt || getDbTimestamp())
    };
  }
  return entry as ProductionEntry;
};

// Normalizer for Activity Logs
const normalizeLog = (data: any): ActivityLog => {
  if (!data) return {} as ActivityLog;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      timestamp: String(data[1] || getDbTimestamp()),
      userId: String(data[2] || ''),
      userName: String(data[3] || 'System'),
      action: String(data[4] || 'LOG'),
      details: String(data[5] || '')
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now()),
    timestamp: String(data.timestamp || getDbTimestamp()),
    userName: String(data.userName || 'Unknown'),
    details: String(data.details || '')
  };
};

// Normalizer for Off Days
const normalizeOffDay = (data: any): OffDay => {
  if (!data) return {} as OffDay;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      date: String(data[1] || '').split(' ')[0],
      description: String(data[2] || 'Holiday'),
      createdBy: String(data[3] || 'System')
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now()),
    date: String(data.date || '').split(' ')[0],
    description: String(data.description || 'Holiday')
  };
};

const init = () => {
  if (!localStorage.getItem(KEYS.USERS)) {
    localStorage.setItem(KEYS.USERS, JSON.stringify(INITIAL_USERS));
  }
  if (!localStorage.getItem(KEYS.OFF_DAYS)) {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(INITIAL_OFF_DAYS));
  }
  if (!localStorage.getItem(KEYS.PRODUCTION)) {
    const seed = generateSeedProductionData().map(p => ({
      ...p,
      status: p.actualQuantity > 0 ? 'Completed' : 'In Progress'
    }));
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(seed));
  }
  if (!localStorage.getItem(KEYS.LOGS)) {
    localStorage.setItem(KEYS.LOGS, JSON.stringify([]));
  }
};

init();

export const StorageService = {
  getUsers: (): User[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.USERS) || '[]');
      return Array.isArray(data) ? data : [];
    } catch { return []; }
  },
  saveUsers: (users: User[]) => {
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    GoogleSheetsService.saveData('saveUsers', users);
  },

  getProductionData: (): ProductionEntry[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.PRODUCTION) || '[]');
      return Array.isArray(data) ? data.map(normalizeProduction).filter(p => p.date && p.date.length > 0) : [];
    } catch { return []; }
  },
  saveProductionData: (data: ProductionEntry[]) => {
    const cleaned = data.map(normalizeProduction).filter(p => p.date && p.date.length > 0);
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(cleaned));
    GoogleSheetsService.saveData('saveProduction', cleaned);
  },

  deleteProductionEntry: (id: string): { updatedData: ProductionEntry[], deletedItem: ProductionEntry | null } => {
    try {
      const data = StorageService.getProductionData();
      const targetId = String(id);
      const targetItem = data.find(p => String(p.id) === targetId) || null;
      const updatedData = data.filter(p => String(p.id) !== targetId);
      StorageService.saveProductionData(updatedData);
      return { updatedData, deletedItem: targetId ? targetItem : null };
    } catch (err) {
      console.error("Storage delete error:", err);
      return { updatedData: StorageService.getProductionData(), deletedItem: null };
    }
  },

  getOffDays: (): OffDay[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.OFF_DAYS) || '[]');
      return Array.isArray(data) ? data.map(normalizeOffDay).filter(od => od.date && od.date.length > 0) : [];
    } catch { return []; }
  },
  saveOffDays: (days: OffDay[]) => {
    const cleaned = days.map(normalizeOffDay).filter(od => od.date && od.date.length > 0);
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(cleaned));
    GoogleSheetsService.saveData('saveOffDays', cleaned);
  },

  syncWithSheets: async () => {
    if (!GoogleSheetsService.isEnabled()) return;

    try {
      const results = await Promise.all([
        GoogleSheetsService.fetchData<any[]>('getProduction'),
        GoogleSheetsService.fetchData<any[]>('getOffDays'),
        GoogleSheetsService.fetchData<any[]>('getLogs'),
        GoogleSheetsService.fetchData<User[]>('getUsers')
      ]);

      if (results[0] && Array.isArray(results[0])) {
          const cleaned = results[0].map(normalizeProduction).filter(p => p.date && p.date.length > 0);
          localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(cleaned));
      }

      if (results[1] && Array.isArray(results[1])) {
          const cleaned = results[1].map(normalizeOffDay).filter(od => od.date && od.date.length > 0);
          localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(cleaned));
      }

      if (results[2] && Array.isArray(results[2])) {
          const cleanedLogs = results[2].map(normalizeLog).filter(l => l.timestamp);
          localStorage.setItem(KEYS.LOGS, JSON.stringify(cleanedLogs));
      }

      if (results[3] && Array.isArray(results[3])) {
          localStorage.setItem(KEYS.USERS, JSON.stringify(results[3]));
      }
    } catch (err) {
      console.error("Critical Sync Failure:", err);
      throw err;
    }
  },

  getLogs: (): ActivityLog[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]');
      return Array.isArray(data) ? data.map(normalizeLog) : [];
    } catch { return []; }
  },
  addLog: (log: Omit<ActivityLog, 'id' | 'timestamp'>) => {
    try {
      const logs = StorageService.getLogs();
      const newLog: ActivityLog = {
        ...log,
        id: Date.now().toString(),
        timestamp: getDbTimestamp(),
      };
      logs.unshift(newLog);
      if (logs.length > 500) logs.pop(); 

      localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
      GoogleSheetsService.saveData('saveLogs', logs);
    } catch (err) {
      console.error("Logging error:", err);
    }
  },

  getSession: (): User | null => {
    try {
      const session = localStorage.getItem(KEYS.CURRENT_USER);
      return session ? JSON.parse(session) : null;
    } catch { return null; }
  },
  setSession: (user: User | null) => {
    if (user) localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    else localStorage.removeItem(KEYS.CURRENT_USER);
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { ProductionEntry, Category, ProcessType, UnitType, ProductionStatus } from '../../types';
import { X, Loader2, AlertTriangle, Palmtree, MessageSquare } from 'lucide-react';
import { getTodayISO, getDbTimestamp } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState<UnitType>('KG');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');
  const [planRemark, setPlanRemark] = useState('');
  const [actualRemark, setActualRemark] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);
  const currentOffDay = useMemo(() => {
    const inputDate = (date || '').trim().split(' ')[0];
    return offDays.find(od => (od.date || '').trim().split(' ')[0] === inputDate);
  }, [date, offDays]);

  const availableProcesses = useMemo(() => {
    if (['Toothpaste', 'Rocksalt', 'Cosmetic'].includes(category)) {
      return PROCESSES.filter(p => p !== 'Encapsulation');
    }
    return [...PROCESSES];
  }, [category]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (!availableProcesses.includes(process)) {
      setProcess(availableProcesses[0]);
    }
  }, [category, availableProcesses, process]);

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().split(' ')[0]);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setUnit(editEntry.unit || 'KG');

      if (editEntry.actualQuantity > 0) {
        setTab('Actual');
        setQuantity(editEntry.actualQuantity.toString());
      } else {
        setTab('Plan');
        setQuantity(editEntry.planQuantity.toString());
      }

      setManpower(editEntry.manpower ? Number(editEntry.manpower).toString() : '0');
      setBatchNo(editEntry.batchNo || '');
      setPlanRemark(editEntry.planRemark || '');
      setActualRemark(editEntry.actualRemark || '');
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const normalizedInputDate = (date || '').trim().split(' ')[0];
        const relevant = all.filter(p => (p.date || '').trim().split(' ')[0] === normalizedInputDate);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  useEffect(() => {
    if (tab === 'Actual' && selectedPlanId && !editEntry) {
        const target = plans.find(p => p.id === selectedPlanId);
        if (target) {
            setUnit(target.unit || 'KG');
        }
    }
  }, [selectedPlanId, tab, plans, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    const normalizedDate = (date || '').trim().split(' ')[0];

    if (!editEntry && currentOffDay) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: `ENTRY RESTRICTED: Today is ${currentOffDay.description}`, type: 'info' } 
        }));
        setIsSubmitting(false);
        return;
    }

    const currentData = StorageService.getProductionData();
    // Rule: Plan only = In Progress, Actual submitted = Completed
    const determinedStatus: ProductionStatus = tab === 'Actual' ? 'Completed' : 'In Progress';

    try {
        if (editEntry) {
            const updated = currentData.map(p => {
                if (p.id === editEntry.id) {
                    const newQty = parseInt(quantity || '0');
                    // Fix: Explicitly cast the returned object to ProductionEntry to avoid status type inference issues
                    return { 
                        ...p, 
                        date: normalizedDate, 
                        category, process, productName, unit,
                        planQuantity: tab === 'Plan' ? newQty : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? newQty : p.actualQuantity,
                        batchNo, manpower: parseFloat(manpower || '0'),
                        planRemark,
                        actualRemark,
                        status: (tab === 'Actual' && newQty > 0 ? 'Completed' : p.status) as ProductionStatus,
                        lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                    } as ProductionEntry;
                }
                return p;
            });

            StorageService.saveProductionData(updated);
            StorageService.addLog({
              userId: user!.id,
              userName: user!.name,
              action: 'EDIT_RECORD',
              details: `Updated record ${productName} (Status: ${determinedStatus})`
            });
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date: normalizedDate, 
                    category, process, productName, unit,
                    planQuantity: parseInt(quantity || '0'), actualQuantity: 0,
                    planRemark,
                    actualRemark: '',
                    status: 'In Progress',
                    lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'CREATE_PLAN',
                  details: `Planned ${newEntry.planQuantity} ${newEntry.unit} for ${newEntry.productName}`
                });
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const updated = currentData.map(p => {
                    if (p.id === selectedPlanId) {
                        // Fix: Explicitly cast the returned object to ProductionEntry to avoid status type inference issues
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity || '0'), 
                            unit, 
                            batchNo, 
                            manpower: parseFloat(manpower || '0'),
                            actualRemark,
                            status: 'Completed' as ProductionStatus,
                            lastUpdatedBy: user!.id, 
                            updatedAt: getDbTimestamp()
                        } as ProductionEntry;
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
                StorageService.addLog({
                  userId: user!.id,
                  userName: user!.name,
                  action: 'RECORD_ACTUAL',
                  details: `Recorded actual output for ${productName} (Marked as Completed)`
                });
            }
        }

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: determinedStatus === 'Completed' ? 'PRODUCTION COMPLETED & SAVED' : 'PRODUCTION PLAN SAVED', type: 'success' } 
        }));

        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: err.message || 'Operation failed', type: 'info' } 
        }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative max-h-[90vh] flex flex-col">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-[60] flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Uploading to Cloud...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700 shrink-0">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        1. Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-500 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        2. Record Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 flex overflow-hidden">
                <button onClick={() => setTab('Plan')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600 bg-indigo-50/10' : 'border-transparent text-slate-400'}`}>
                    Plan Details
                </button>
                <button onClick={() => setTab('Actual')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Actual' ? 'border-emerald-500 text-emerald-600 bg-emerald-50/10' : 'border-transparent text-slate-400'}`}>
                    Actual Results
                </button>
              </div>
            )}
        </div>

        <div className="p-6 relative overflow-y-auto custom-scrollbar flex-1">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors z-20"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {currentOffDay && (
                      <div className="mt-3 p-3 bg-amber-50 dark:bg-amber-900/20 border border-amber-300 dark:border-amber-700 rounded-xl flex items-center gap-3 animate-pulse shadow-sm">
                        <div className="p-2 bg-amber-500 text-white rounded-lg shadow-md">
                          <Palmtree className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className="text-[10px] font-black text-amber-700 dark:text-amber-400 uppercase tracking-widest leading-none mb-1">Public Holiday</p>
                          <p className="text-xs font-black text-slate-900 dark:text-amber-50">{currentOffDay.description || 'OFF DAY'}</p>
                        </div>
                      </div>
                    )}
                </div>

                {tab === 'Plan' ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {availableProcesses.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input 
                              type="text" 
                              required 
                              value={productName} 
                              onChange={e => setProductName(e.target.value.toUpperCase())} 
                              className={inputClasses} 
                              placeholder="Enter product name..." 
                            />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="flex-1">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Target Plan Qty</label>
                                <input type="number" required min="1" value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                            </div>
                            <div className="w-24">
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                    {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5">
                              <MessageSquare className="w-3 h-3" /> Plan Remark
                            </label>
                            <textarea 
                                value={planRemark} 
                                onChange={e => setPlanRemark(e.target.value.toUpperCase())} 
                                className={`${inputClasses} h-20 resize-none font-medium text-xs`}
                                placeholder="ADD PLANNING NOTES..."
                            />
                        </div>
                    </>
                ) : (
                    <>
                        {!editEntry && (
                          <div className="mb-4">
                               <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Select Pending Job</label>
                               {plans.length === 0 ? <div className="text-xs text-slate-400 italic text-center p-6 border-2 border-dashed rounded-xl">No plans found for this date.</div> : (
                                   <div className="max-h-40 overflow-y-auto border rounded-xl p-2 space-y-1 dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
                                       {plans.map(p => (
                                           <div key={p.id} onClick={() => { setSelectedPlanId(p.id); setProductName(p.productName); setProcess(p.process); setCategory(p.category); }}
                                              className={`p-3 rounded-lg cursor-pointer transition ${selectedPlanId === p.id ? 'bg-emerald-600 text-white shadow-md' : 'text-slate-600 dark:text-slate-300 hover:bg-white dark:hover:bg-slate-800'}`}>
                                              <div className="font-black text-sm">{p.productName}</div>
                                              <div className={`text-[10px] font-bold uppercase ${selectedPlanId === p.id ? 'text-emerald-100' : 'text-slate-400'}`}>{p.process} • Plan: {p.planQuantity} {p.unit || 'KG'}</div>
                                           </div>
                                       ))}
                                   </div>
                               )}
                          </div>
                        )}
                        {(selectedPlanId || editEntry) && (
                            <>
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="flex-1">
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Actual Result Qty</label>
                                        <input type="number" required value={quantity} onChange={e => setQuantity(e.target.value)} className={inputClasses} />
                                    </div>
                                    <div className="w-24">
                                        <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Unit</label>
                                        <select value={unit} onChange={e => setUnit(e.target.value as UnitType)} className={inputClasses}>
                                            {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                                        </select>
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                  <div className="col-span-2">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Batch Number</label>
                                    <input type="text" required value={batchNo} onChange={e => setBatchNo(e.target.value)} className={inputClasses} placeholder="Enter batch ID..." />
                                  </div>
                                  <div className="col-span-2">
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Manpower Used</label>
                                    <input type="number" required step="any" value={manpower} onChange={e => setManpower(e.target.value)} className={inputClasses} />
                                  </div>
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 flex items-center gap-1.5">
                                      <MessageSquare className="w-3 h-3" /> Actual Remark
                                    </label>
                                    <textarea 
                                        value={actualRemark} 
                                        onChange={e => setActualRemark(e.target.value.toUpperCase())} 
                                        className={`${inputClasses} h-20 resize-none font-medium text-xs`}
                                        placeholder="ADD ACTUAL NOTES..."
                                    />
                                </div>
                            </>
                        )}
                    </>
                )}

                <button 
                    type="submit" 
                    disabled={isSubmitting || (!editEntry && !!currentOffDay)} 
                    className={`w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] text-white mt-4 shadow-xl transition hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed ${
                        !!currentOffDay && !editEntry ? 'bg-amber-600' : 
                        tab === 'Plan' ? 'bg-slate-900 dark:bg-indigo-600 shadow-indigo-500/10' : 
                        'bg-emerald-600 shadow-emerald-500/10'
                    }`}
                >
                    {isSubmitting ? 'Syncing...' : (!!currentOffDay && !editEntry ? 'Holiday Entry Locked' : (tab === 'Actual' ? 'Submit & Mark Completed' : 'Save Plan Entry'))}
                </button>
            </form>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, List, Calendar, 
  Download, Pencil, Trash2, Layers,
  Palmtree, MessageSquare, ArrowUpDown, Clock, CheckCircle
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

type SortConfig = {
    key: keyof ProductionEntry | 'status';
    direction: 'asc' | 'desc';
} | null;

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry | 'status') => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);

    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;

    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();

    const validProcesses = ['Toothpaste', 'Rocksalt', 'Cosmetic'].includes(category)
      ? PROCESSES.filter(p => p !== 'Encapsulation')
      : [...PROCESSES];

    validProcesses.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);

        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const filteredOffDays = offDays.filter(od => od && od.date && od.date.trim().startsWith(selectedMonth));

    const dates = new Set<string>();
    filteredEntries.forEach(d => {
      if (d.date) dates.add(d.date.trim().substring(0, 10));
    });
    filteredOffDays.forEach(od => {
      if (od.date) dates.add(od.date.trim().substring(0, 10));
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));

    return sortedDates.map(dateKey => {
        let entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);

        // Apply internal sorting if configured
        if (sortConfig) {
            entriesForDate = [...entriesForDate].sort((a, b) => {
                const aValue = a[sortConfig.key] || '';
                const bValue = b[sortConfig.key] || '';
                if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
                return 0;
            });
        }

        const offDayInfo = filteredOffDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            isOffDay: !!offDayInfo,
            offDayName: offDayInfo?.description || ''
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth, sortConfig]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Are you sure you want to PERMANENTLY delete this record? This action cannot be undone.")) return;

      const { deletedItem } = StorageService.deleteProductionEntry(id);

      if (deletedItem) {
          StorageService.addLog({
            userId: user!.id,
            userName: user!.name,
            action: 'DELETE_RECORD',
            details: `Admin/Manager/Planner permanently deleted production record: ${deletedItem.productName} (${deletedItem.date})`
          });

          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD DELETED SUCCESSFULLY', type: 'info' } 
          }));
      }

      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const downloadCSV = () => {
    const headers = ["Date", "Status Shift", "Process", "Product", "Plan", "Actual", "Unit", "Batch No", "Manpower", "Plan Remark", "Actual Remark", "Status"];
    const rows = dailyGroups.flatMap(g => {
        if (g.entries.length === 0) {
            return [[g.date, g.offDayName || 'Off Day', '-', '-', 0, 0, '-', '-', 0, '-', '-', '-']];
        }
        return g.entries.map(d => [
            d.date, g.isOffDay ? `Holiday (${g.offDayName})` : 'Normal', d.process, d.productName, d.planQuantity, d.actualQuantity, d.unit || 'KG', d.batchNo, d.manpower, (d.planRemark || '').replace(/,/g, ';'), (d.actualRemark || '').replace(/,/g, ';'), d.status || 'In Progress'
        ]);
    });
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Halagel_Full_Report_${category}_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();

    StorageService.addLog({
      userId: user!.id,
      userName: user!.name,
      action: 'EXPORT_REPORT',
      details: `Exported full report for ${category} (${selectedMonth})`
    });

    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  const SortHeader = ({ label, sortKey }: { label: string, sortKey: keyof ProductionEntry | 'status' }) => (
    <th className="px-8 py-4 cursor-pointer group" onClick={() => handleSort(sortKey)}>
        <div className="flex items-center gap-1">
            {label}
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100 text-indigo-500' : 'opacity-0 group-hover:opacity-40'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-8 pb-12">
      {/* MONTHLY PROCESS BREAKDOWN */}
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
            <Layers className="w-4 h-4 text-indigo-500" />
            <h3 className="text-[12px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.3em]">Monthly Process Breakdown</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-800 shadow-sm group hover:border-indigo-500/30 transition-all duration-300">
                        <div className="flex items-center justify-between mb-6">
                          <p className="text-sm font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{item.process}</p>
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse" />
                        </div>

                        <div className="space-y-5">
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-tighter">Planned Output</span>
                                <span className="text-2xl font-black text-slate-800 dark:text-white font-mono leading-none">{(item.Plan || 0).toLocaleString()}</span>
                            </div>

                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-tighter">Actual Result</span>
                                <span className="text-2xl font-black text-emerald-500 font-mono leading-none">{(item.Actual || 0).toLocaleString()}</span>
                            </div>

                            <div className="pt-5 border-t border-gray-50 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Efficiency</span>
                                <span className={`text-xl font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(1)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      {/* Daily Logs */}
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Operational granularity for {selectedMonth}</p>
            </div>

            <div className="flex items-center gap-3">
              <input 
                type="month" 
                value={selectedMonth} 
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none"
              />
              <button onClick={downloadCSV} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white text-xs font-black rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-500/20 uppercase tracking-widest transition">
                <Download className="w-4 h-4" /> Export Report
              </button>
            </div>
        </div>

        <div className="space-y-6">
            {dailyGroups.length === 0 ? (
                <div className="glass-panel p-16 rounded-[2rem] text-center">
                    <div className="flex flex-col items-center gap-4">
                        <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-full text-slate-200">
                            <ClipboardList className="w-12 h-12" />
                        </div>
                        <p className="text-slate-400 font-bold uppercase tracking-widest">No production logs found for the selected month.</p>
                        <p className="text-xs text-slate-400">Try changing the category or month filter.</p>
                    </div>
                </div>
            ) : dailyGroups.map((group, groupIdx) => {
                const displayDate = formatDisplayDate(group.date);
                const [datePart, dayPart] = displayDate.split(' ');

                return (
                  <div key={`group-${groupIdx}`} className={`bg-white dark:bg-slate-850 rounded-[2rem] overflow-hidden shadow-sm border ${group.isOffDay ? 'border-amber-400/50' : 'border-gray-100 dark:border-slate-800'}`}>
                      <div className={`p-6 flex justify-between items-center border-b ${group.isOffDay ? 'bg-amber-50 dark:bg-amber-900/10 border-amber-100 dark:border-amber-900/30' : 'border-gray-100 dark:border-slate-800 bg-gray-50/50 dark:bg-slate-800/50'}`}>
                          <div className="flex items-center gap-4">
                              {group.isOffDay ? <Palmtree className="w-6 h-6 text-amber-500" /> : <Calendar className="w-6 h-6 text-slate-400" />}
                              <div className="flex items-center gap-3">
                                <span className={`text-xl font-black ${group.isOffDay ? 'text-amber-700 dark:text-amber-400' : 'text-slate-800 dark:text-white'}`}>{datePart}</span>
                                <span className={`text-xl font-medium uppercase tracking-tight ${group.isOffDay ? 'text-amber-800' : 'text-slate-800 dark:text-slate-200'}`}>
                                  {dayPart}
                                </span>
                              </div>
                              {group.isOffDay && (
                                <span className="px-3 py-1 bg-amber-500 text-white text-[9px] font-black uppercase rounded-full shadow-sm tracking-widest">
                                    {group.offDayName || 'OFF DAY'}
                                </span>
                              )}
                          </div>
                          <div className="px-4 py-1.5 bg-white dark:bg-slate-900 rounded-xl border border-gray-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 font-black text-[11px] uppercase tracking-widest">
                            Actual: <span className="text-emerald-500 ml-1 font-mono">{(group.totalActualForDate || 0).toLocaleString()}</span>
                          </div>
                      </div>

                      {group.entries.length > 0 ? (
                        <div className="overflow-x-auto no-scrollbar">
                            <table className="w-full text-left">
                                <thead>
                                    <tr className="border-b border-gray-50 dark:border-slate-800 text-[9px] font-black text-slate-400 uppercase tracking-widest bg-gray-50/30 dark:bg-slate-900/30">
                                        <SortHeader label="Process" sortKey="process" />
                                        <SortHeader label="Product Name" sortKey="productName" />
                                        <th className="px-8 py-4 text-right">Plan Qty</th>
                                        <th className="px-8 py-4 text-right">Actual Qty</th>
                                        <th className="px-8 py-4 text-center">Efficiency</th>
                                        <th className="px-8 py-4 text-center">Batch No</th>
                                        <th className="px-8 py-4 text-center">Manpower</th>
                                        <SortHeader label="Status" sortKey="status" />
                                        {hasPermission(['admin', 'manager', 'planner']) && <th className="px-8 py-4 text-center">Action</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-gray-50 dark:divide-slate-800/30">
                                    {group.entries.map(entry => {
                                        const eff = entry.planQuantity > 0 ? (entry.actualQuantity / entry.planQuantity) * 100 : 0;
                                        const isCompleted = entry.status === 'Completed';
                                        return (
                                            <tr key={entry.id} className="hover:bg-gray-50/50 dark:hover:bg-slate-800/30 transition-colors">
                                                <td className="px-8 py-5">
                                                    <span className="text-[10px] font-black text-indigo-600 dark:text-indigo-400 uppercase bg-indigo-50 dark:bg-indigo-900/30 px-2 py-1 rounded-lg border border-indigo-100 dark:border-indigo-800">{entry.process}</span>
                                                </td>
                                                <td className="px-8 py-5">
                                                    <div className="flex flex-col">
                                                      <span className="text-sm font-black text-slate-800 dark:text-white">{entry.productName}</span>
                                                    </div>
                                                </td>
                                                <td className="px-8 py-5 text-right font-black font-mono text-indigo-600/80 dark:text-indigo-400/80 text-sm whitespace-nowrap">
                                                    <div>{(entry.planQuantity || 0).toLocaleString()} <span className="text-[9px] ml-1 opacity-60 text-slate-600 dark:text-slate-400 font-sans tracking-tight">{entry.unit}</span></div>
                                                    {entry.planRemark && (
                                                      <div className="flex items-center justify-end gap-1 mt-1">
                                                        <MessageSquare className="w-3 h-3 text-slate-300 shrink-0" />
                                                        <span className="text-[9px] font-medium text-slate-400 italic max-w-[150px] whitespace-normal text-right">{entry.planRemark}</span>
                                                      </div>
                                                    )}
                                                </td>
                                                <td className="px-8 py-5 text-right font-black font-mono text-emerald-500 text-sm whitespace-nowrap">
                                                    <div>{(entry.actualQuantity || 0).toLocaleString()} <span className="text-[9px] ml-1 opacity-60 text-slate-600 dark:text-slate-400 font-sans tracking-tight">{entry.unit}</span></div>
                                                    {entry.actualRemark && (
                                                      <div className="flex items-center justify-end gap-1 mt-1">
                                                        <MessageSquare className="w-3 h-3 text-emerald-200 shrink-0" />
                                                        <span className="text-[9px] font-medium text-emerald-400/80 italic max-w-[150px] whitespace-normal text-right">{entry.actualRemark}</span>
                                                      </div>
                                                    )}
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className={`text-sm font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                                        {(eff || 0).toFixed(0)}%
                                                    </span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-[11px] font-bold text-slate-400 uppercase tracking-tighter font-mono">{entry.batchNo || '-'}</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <span className="text-base font-black text-slate-800 dark:text-white font-mono">{Number(entry.manpower || 0)}</span>
                                                </td>
                                                <td className="px-8 py-5 text-center">
                                                    <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-tight border ${
                                                        isCompleted ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-indigo-50 text-indigo-600 border-indigo-200'
                                                    }`}>
                                                        {isCompleted ? <CheckCircle className="w-3 h-3" /> : <Clock className="w-3 h-3 animate-pulse" />}
                                                        {entry.status || 'In Progress'}
                                                    </div>
                                                </td>
                                                {hasPermission(['admin', 'manager', 'planner']) && (
                                                  <td className="px-8 py-5">
                                                      <div className="flex items-center justify-center gap-2">
                                                          <button onClick={() => handleEdit(entry)} className="p-1.5 text-indigo-400 hover:bg-indigo-50 dark:hover:bg-indigo-900/30 rounded-lg transition">
                                                              <Pencil className="w-4 h-4" />
                                                          </button>
                                                          <button onClick={() => handleDelete(entry.id)} className="p-1.5 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-lg transition">
                                                              <Trash2 className="w-4 h-4" />
                                                          </button>
                                                      </div>
                                                  </td>
                                                )}
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                      ) : (
                        <div className="p-10 text-center text-slate-400 text-xs italic font-bold uppercase tracking-widest">
                            No production activity recorded for this date.
                        </div>
                      )}
                  </div>
                );
            })}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { Trash2, Download, Calendar, List, Filter, XCircle, Palmtree, BarChart2, MessageSquare, ArrowUpDown, Clock, CheckCircle } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, 
  ResponsiveContainer, LineChart, Line, AreaChart, Area, ComposedChart,
  Cell
} from 'recharts';

type SortConfig = {
    key: keyof ProductionEntry | 'status';
    direction: 'asc' | 'desc';
} | null;

export const ProductionLog: React.FC = () => {
  const { user, hasPermission } = useAuth();
  const { refreshKey, triggerRefresh, isDarkMode } = useDashboard();
  const [data, setData] = useState<ProductionEntry[]>([]);
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);
  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [category, setCategory] = useState('All');
  const [processType, setProcessType] = useState('All');

  useEffect(() => {
    setData(StorageService.getProductionData());
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry | 'status') => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const filteredData = useMemo(() => {
    let result = data.filter(d => {
      if (!d) return false;
      const matchCat = category === 'All' || d.category === category;
      const matchProc = processType === 'All' || d.process === processType;
      const matchStart = !dateRange.start || (d.date && d.date >= dateRange.start);
      const matchEnd = !dateRange.end || (d.date && d.date <= dateRange.end);
      return matchCat && matchProc && matchStart && matchEnd;
    });

    if (sortConfig) {
        result = [...result].sort((a, b) => {
            const aVal = (a[sortConfig.key] || '').toString();
            const bVal = (b[sortConfig.key] || '').toString();
            if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
    } else {
        result.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    }

    return result;
  }, [data, dateRange, category, processType, sortConfig]);

  // Breakdown by Month + Process for the table
  const monthlyData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number, count: number, month: string, process: string }> = {};

    filteredData.forEach(d => {
        if (!d.date) return;
        const monthKey = d.date.substring(0, 7); 
        const procKey = d.process || 'Other';
        const compositeKey = `${monthKey}_${procKey}`;

        if (!groups[compositeKey]) {
            groups[compositeKey] = { plan: 0, actual: 0, count: 0, month: monthKey, process: procKey };
        }
        groups[compositeKey].plan += (d.planQuantity || 0);
        groups[compositeKey].actual += (d.actualQuantity || 0);
        groups[compositeKey].count++;
    });

    return Object.values(groups)
        .map((stats) => ({
            name: stats.month, // month label
            process: stats.process,
            plan: stats.plan,
            actual: stats.actual,
            efficiency: stats.plan > 0 ? Number(((stats.actual / stats.plan) * 100).toFixed(1)) : 0
        }))
        .sort((a, b) => {
            const monthCompare = b.name.localeCompare(a.name);
            if (monthCompare !== 0) return monthCompare;
            return a.process.localeCompare(b.process);
        }); 
  }, [filteredData]);

  // Aggregated data for the Monthly chart (Total per month)
  const monthlyChartSummaryData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number }> = {};
    filteredData.forEach(d => {
      if (!d.date) return;
      const monthKey = d.date.substring(0, 7);
      if (!groups[monthKey]) groups[monthKey] = { plan: 0, actual: 0 };
      groups[monthKey].plan += (d.planQuantity || 0);
      groups[monthKey].actual += (d.actualQuantity || 0);
    });

    return Object.entries(groups)
      .map(([month, stats]) => ({
        name: month,
        plan: stats.plan,
        actual: stats.actual,
        efficiency: stats.plan > 0 ? Number(((stats.actual / stats.plan) * 100).toFixed(1)) : 0
      }))
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [filteredData]);

  // Data for the Daily Chart (Top 10 products by Plan)
  const chartDailyData = useMemo(() => {
    const products: Record<string, { plan: number, actual: number }> = {};
    filteredData.forEach(d => {
        const key = d.productName;
        if (!products[key]) products[key] = { plan: 0, actual: 0 };
        products[key].plan += d.planQuantity;
        products[key].actual += d.actualQuantity;
    });

    return Object.entries(products)
        .map(([name, stats]) => ({
            name: name.length > 15 ? name.substring(0, 15) + '...' : name,
            fullName: name,
            plan: stats.plan,
            actual: stats.actual
        }))
        .sort((a, b) => b.plan - a.plan)
        .slice(0, 10);
  }, [filteredData]);

  const handleDelete = (id: string) => {
    if (!window.confirm("Are you sure you want to PERMANENTLY delete this entry?")) return;
    const { deletedItem } = StorageService.deleteProductionEntry(id);
    if (deletedItem) {
        StorageService.addLog({
          userId: user!.id,
          userName: user!.name,
          action: 'DELETE_RECORD',
          details: `Record deleted from reports: ${deletedItem.productName} (${deletedItem.date})`
        });
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD REMOVED SUCCESSFULLY', type: 'info' } 
        }));
    }
    triggerRefresh();
  };

  const resetFilters = () => {
    setDateRange({ start: '', end: '' });
    setCategory('All');
    setProcessType('All');
    setSortConfig(null);
  };

  const calculateEfficiency = (actual: number, plan: number) => {
    if (!plan || plan === 0) return 0;
    return ((actual / plan) * 100).toFixed(1);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';
    const today = getTodayISO();

    if (viewMode === 'daily') {
        headers = ["Date", "Status Shift", "Category", "Process", "Product", "Plan", "Actual", "Unit", "Efficiency %", "Batch No", "Manpower", "Status", "Plan Remark", "Actual Remark"];
        rows = filteredData.map(d => {
            const isOff = offDays.some(od => od.date === d.date);
            return [
                d.date, isOff ? 'Holiday Shift' : 'Normal', d.category, d.process, `"${d.productName}"`, d.planQuantity || 0, d.actualQuantity || 0, d.unit || 'KG',
                calculateEfficiency(d.actualQuantity || 0, d.planQuantity || 0), d.batchNo || '', Number(d.manpower || 0), d.status || 'In Progress', `"${(d.planRemark || '').replace(/"/g, '""')}"`, `"${(d.actualRemark || '').replace(/"/g, '""')}"`
            ];
        });
        filename = `production_log_daily_${today}.csv`;
    } else {
        headers = ["Month", "Process", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [ m.name, m.process, m.plan || 0, m.actual || 0, (m.efficiency || 0).toFixed(2) ]);
        filename = `production_summary_monthly_${today}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  const SortHeader = ({ label, sortKey, align = 'left' }: { label: string, sortKey: keyof ProductionEntry | 'status', align?: 'left' | 'right' | 'center' }) => (
    <th className={`px-8 py-5 cursor-pointer group text-${align}`} onClick={() => handleSort(sortKey)}>
        <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : ''}`}>
            {label}
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100 text-indigo-50' : 'opacity-0 group-hover:opacity-60'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-black text-gray-800 dark:text-white">Production Analytics</h2>

        <div className="flex items-center bg-white dark:bg-slate-800 rounded-xl p-1.5 border border-gray-200 dark:border-slate-700 shadow-sm">
            <button onClick={() => setViewMode('daily')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition ${viewMode === 'daily' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500 hover:text-indigo-600'}`}>
                <List className="w-4 h-4" /> Daily
            </button>
            <button onClick={() => setViewMode('monthly')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition ${viewMode === 'monthly' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500 hover:text-indigo-600'}`}>
                <Calendar className="w-4 h-4" /> Monthly
            </button>
        </div>

        <button onClick={downloadCSV} className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-emerald-700 transition shadow-lg shadow-emerald-500/20">
            <Download className="w-4 h-4" /> Export Report
        </button>
      </div>

      {/* FILTER PANEL */}
      <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 shadow-sm border border-gray-100 dark:border-slate-700 flex flex-wrap gap-6 items-end">
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1">
            <Filter className="w-3 h-3" /> Date From
          </label>
          <input 
            type="date" 
            value={dateRange.start} 
            onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))}
            className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 w-full sm:w-auto font-bold dark:text-white"
          />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1">
            <Filter className="w-3 h-3" /> Date To
          </label>
          <input 
            type="date" 
            value={dateRange.end} 
            onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))}
            className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 w-full sm:w-auto font-bold dark:text-white"
          />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Department</label>
          <select 
            value={category} 
            onChange={e => setCategory(e.target.value)}
            className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 min-w-[160px] font-bold dark:text-white"
          >
            <option value="All">All Departments</option>
            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Process</label>
          <select 
            value={processType} 
            onChange={e => setProcessType(e.target.value)}
            className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 min-w-[160px] font-bold dark:text-white"
          >
            <option value="All">All Processes</option>
            {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
        <button 
          onClick={resetFilters}
          className="flex items-center gap-1.5 px-4 py-2.5 text-[10px] font-black uppercase tracking-widest text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-xl transition"
        >
          <XCircle className="w-4 h-4" /> Reset
        </button>
      </div>

      {/* CHART SECTION */}
      <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700">
        <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
                <BarChart2 className="w-5 h-5 text-indigo-500" />
                <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">
                    {viewMode === 'daily' ? 'Filtered Product Performance (Top 10)' : 'Monthly Overall Efficiency'}
                </h3>
            </div>
            {viewMode === 'monthly' && (
                <div className="flex items-center gap-6">
                    <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full bg-indigo-500"></div>
                        <span className="text-[10px] font-black text-slate-400 uppercase">Plan</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full bg-emerald-500"></div>
                        <span className="text-[10px] font-black text-slate-400 uppercase">Actual</span>
                    </div>
                </div>
            )}
        </div>

        <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={viewMode === 'daily' ? chartDailyData : monthlyChartSummaryData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? '#334155' : '#f1f5f9'} />
                    <XAxis 
                        dataKey="name" 
                        axisLine={false} 
                        tickLine={false} 
                        tick={{ fontSize: 10, fontWeight: 800, fill: isDarkMode ? '#94a3b8' : '#64748b' }} 
                        dy={10}
                    />
                    <YAxis 
                        axisLine={false} 
                        tickLine={false} 
                        tick={{ fontSize: 10, fontWeight: 800, fill: isDarkMode ? '#94a3b8' : '#64748b' }} 
                    />
                    <Tooltip 
                        cursor={{ fill: isDarkMode ? '#1e293b' : '#f8fafc' }}
                        contentStyle={{ 
                            backgroundColor: isDarkMode ? '#1e293b' : '#ffffff', 
                            borderRadius: '16px', 
                            border: 'none', 
                            boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)',
                            fontSize: '12px',
                            fontWeight: 'bold'
                        }}
                    />
                    <Bar dataKey="plan" name="Target Plan" fill="#6366f1" radius={[6, 6, 0, 0]} barSize={viewMode === 'daily' ? 30 : 50} />
                    <Bar dataKey="actual" name="Total Actual" fill="#10b981" radius={[6, 6, 0, 0]} barSize={viewMode === 'daily' ? 30 : 50} />
                    {viewMode === 'monthly' && (
                        <Line type="monotone" dataKey="efficiency" name="Eff. %" stroke="#f59e0b" strokeWidth={3} dot={{ fill: '#f59e0b', r: 4 }} />
                    )}
                </ComposedChart>
            </ResponsiveContainer>
        </div>
      </div>

      {/* DATA TABLE SECTION */}
      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-sm text-left border-collapse">
            <thead className="bg-gray-50/50 dark:bg-slate-900/50 text-slate-400 font-black uppercase text-[10px] tracking-widest border-b dark:border-slate-700">
              {viewMode === 'daily' ? (
                  <tr>
                    <SortHeader label="Date / Status" sortKey="date" />
                    <SortHeader label="Dept" sortKey="category" align="center" />
                    <SortHeader label="Product Name" sortKey="productName" />
                    <th className="px-8 py-5 text-right">Plan & Remark</th>
                    <th className="px-8 py-5 text-right">Actual & Remark</th>
                    <th className="px-8 py-5 text-center">Unit</th>
                    <th className="px-8 py-5 text-right">Eff. %</th>
                    <th className="px-8 py-5 text-center">Manpower</th>
                    <SortHeader label="Status" sortKey="status" align="center" />
                    {hasPermission(['admin', 'manager']) && <th className="px-8 py-5 text-center">Actions</th>}
                  </tr>
              ) : (
                  <tr>
                    <th className="px-8 py-5">Summary Month</th>
                    <th className="px-8 py-5">Process Breakdown</th>
                    <th className="px-8 py-5 text-right">Plan Qty</th>
                    <th className="px-8 py-5 text-right">Actual Qty</th>
                    <th className="px-8 py-5 text-right">Efficiency %</th>
                  </tr>
              )}
            </thead>
            <tbody className="divide-y divide-gray-50 dark:divide-slate-700/50">
              {viewMode === 'daily' ? (
                  filteredData.length === 0 ? (
                    <tr>
                      <td colSpan={10} className="px-8 py-20 text-center text-slate-400 font-bold uppercase tracking-widest italic">No matching records found</td>
                    </tr>
                  ) : filteredData.map(entry => {
                    const eff = Number(calculateEfficiency(entry.actualQuantity || 0, entry.planQuantity || 0));
                    const isOff = entry.date && offDays.some(od => od.date === entry.date);
                    const isCompleted = entry.status === 'Completed';
                    return (
                      <tr key={entry.id} className={`hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition-colors ${isOff ? 'bg-amber-50/10 dark:bg-amber-900/5' : ''}`}>
                        <td className="px-8 py-6">
                            <div className="font-black text-slate-800 dark:text-white mb-1 font-mono text-xs">{entry.date || 'N/A'}</div>
                            {isOff ? (
                                <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-amber-600 dark:text-amber-400">
                                    <Palmtree className="w-3 h-3" /> Holiday
                                </span>
                            ) : (
                                <span className="text-[9px] font-black uppercase text-slate-300">Operational</span>
                            )}
                        </td>
                        <td className="px-8 py-6 text-center">
                          <span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-900 text-slate-500 border border-slate-200 dark:border-slate-800">
                            {entry.category}
                          </span>
                        </td>
                        <td className="px-8 py-6">
                            <div className="font-black text-slate-800 dark:text-white">{entry.productName}</div>
                            <span className="text-[10px] font-black uppercase text-indigo-500 tracking-tight">{entry.process}</span>
                        </td>
                        <td className="px-8 py-6 text-right">
                            <div className="font-black font-mono text-slate-700 dark:text-slate-200">{(entry.planQuantity || 0).toLocaleString()}</div>
                            {entry.planRemark && (
                              <div className="flex items-center justify-end gap-1 mt-1">
                                <MessageSquare className="w-2.5 h-2.5 text-slate-300 shrink-0" />
                                <span className="text-[9px] text-slate-400 italic font-medium whitespace-normal text-right max-w-[150px]">{entry.planRemark}</span>
                              </div>
                            )}
                        </td>
                        <td className="px-8 py-6 text-right">
                            <div className="font-black font-mono text-emerald-500">{(entry.actualQuantity || 0).toLocaleString()}</div>
                            {entry.actualRemark && (
                              <div className="flex items-center justify-end gap-1 mt-1">
                                <MessageSquare className="w-2.5 h-2.5 text-emerald-200 shrink-0" />
                                <span className="text-[9px] text-emerald-400 font-medium italic whitespace-normal text-right max-w-[150px]">{entry.actualRemark}</span>
                              </div>
                            )}
                        </td>
                        <td className="px-8 py-6 text-center">
                          <span className="text-[10px] font-black text-slate-400">{entry.unit || 'KG'}</span>
                        </td>
                        <td className="px-8 py-6 text-right">
                            <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl border font-black text-[11px] ${
                                eff >= 100 ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 
                                eff >= 80 ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 
                                'bg-rose-50 text-rose-600 border-rose-100'
                            }`}>
                                {eff}%
                            </div>
                        </td>
                        <td className="px-8 py-6 text-center font-black font-mono text-slate-800 dark:text-white">
                          {Number(entry.manpower || 0)}
                        </td>
                        <td className="px-8 py-6 text-center">
                            <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-tight border ${
                                isCompleted ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-indigo-50 text-indigo-600 border-indigo-200'
                            }`}>
                                {isCompleted ? <CheckCircle className="w-3 h-3" /> : <Clock className="w-3 h-3 animate-pulse" />}
                                {entry.status || 'In Progress'}
                            </div>
                        </td>
                        {hasPermission(['admin', 'manager']) && (
                            <td className="px-8 py-6 text-center">
                                <button onClick={() => handleDelete(entry.id)} className="text-slate-300 hover:text-rose-500 p-2.5 rounded-xl hover:bg-rose-50 dark:hover:bg-rose-900/20 transition-all">
                                  <Trash2 className="w-4 h-4" />
                                </button>
                            </td>
                        )}
                      </tr>
                    );
                  })
              ) : (
                  monthlyData.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="px-8 py-20 text-center text-slate-400 font-bold uppercase tracking-widest italic">No summaries available</td>
                    </tr>
                  ) : monthlyData.map(m => (
                      <tr key={`${m.name}-${m.process}`} className="hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition">
                          <td className="px-8 py-6 font-black text-slate-800 dark:text-white text-lg">{m.name}</td>
                          <td className="px-8 py-6">
                            <span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border border-indigo-100 dark:border-indigo-800">
                              {m.process}
                            </span>
                          </td>
                          <td className="px-8 py-6 text-right font-mono font-black text-slate-700 dark:text-slate-200">{(m.plan || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-mono font-black text-emerald-500">{(m.actual || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-black">
                            <div className={`inline-flex px-4 py-2 rounded-2xl font-black text-base ${m.efficiency >= 85 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                              {m.efficiency.toFixed(1)}%
                            </div>
                          </td>
                      </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry } from '../../types';
import { Trash2, Download, Calendar, List, Filter, XCircle, Palmtree, BarChart2, MessageSquare, ArrowUpDown, Clock, CheckCircle } from 'lucide-react';
import { getTodayISO } from '../../utils/dateUtils';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, 
  ResponsiveContainer, LineChart, Line, AreaChart, Area, ComposedChart,
  Cell
} from 'recharts';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const ProductionLog: React.FC = () => {
  const { user, hasPermission } = useAuth();
  const { refreshKey, triggerRefresh, isDarkMode } = useDashboard();
  const [data, setData] = useState<ProductionEntry[]>([]);
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);
  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [category, setCategory] = useState('All');
  const [processType, setProcessType] = useState('All');

  useEffect(() => {
    setData(StorageService.getProductionData());
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const filteredData = useMemo(() => {
    let result = data.filter(d => {
      if (!d) return false;
      const matchCat = category === 'All' || d.category === category;
      const matchProc = processType === 'All' || d.process === processType;
      const matchStart = !dateRange.start || (d.date && d.date >= dateRange.start);
      const matchEnd = !dateRange.end || (d.date && d.date <= dateRange.end);
      return matchCat && matchProc && matchStart && matchEnd;
    });

    if (sortConfig) {
        result = [...result].sort((a, b) => {
            const aVal = (a[sortConfig.key] || '').toString();
            const bVal = (b[sortConfig.key] || '').toString();
            if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
    } else {
        result.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    }

    return result;
  }, [data, dateRange, category, processType, sortConfig]);

  // Breakdown by Month + Process for the table
  const monthlyData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number, count: number, month: string, process: string }> = {};

    filteredData.forEach(d => {
        if (!d.date) return;
        const monthKey = d.date.substring(0, 7); 
        const procKey = d.process || 'Other';
        const compositeKey = `${monthKey}_${procKey}`;

        if (!groups[compositeKey]) {
            groups[compositeKey] = { plan: 0, actual: 0, count: 0, month: monthKey, process: procKey };
        }
        groups[compositeKey].plan += (d.planQuantity || 0);
        groups[compositeKey].actual += (d.actualQuantity || 0);
        groups[compositeKey].count++;
    });

    return Object.values(groups)
        .map((stats) => ({
            name: stats.month, // month label
            process: stats.process,
            plan: stats.plan,
            actual: stats.actual,
            efficiency: stats.plan > 0 ? Number(((stats.actual / stats.plan) * 100).toFixed(1)) : 0
        }))
        .sort((a, b) => {
            const monthCompare = b.name.localeCompare(a.name);
            if (monthCompare !== 0) return monthCompare;
            return a.process.localeCompare(b.process);
        }); 
  }, [filteredData]);

  // Aggregated data for the Monthly chart (Total per month)
  const monthlyChartSummaryData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number }> = {};
    filteredData.forEach(d => {
      if (!d.date) return;
      const monthKey = d.date.substring(0, 7);
      if (!groups[monthKey]) groups[monthKey] = { plan: 0, actual: 0 };
      groups[monthKey].plan += (d.planQuantity || 0);
      groups[monthKey].actual += (d.actualQuantity || 0);
    });

    return Object.entries(groups)
      .map(([month, stats]) => ({
        name: month,
        plan: stats.plan,
        actual: stats.actual,
        efficiency: stats.plan > 0 ? Number(((stats.actual / stats.plan) * 100).toFixed(1)) : 0
      }))
      .sort((a, b) => a.name.localeCompare(b.name));
  }, [filteredData]);

  // Data for the Daily Chart (Top 10 products by Plan)
  const chartDailyData = useMemo(() => {
    const products: Record<string, { plan: number, actual: number }> = {};
    filteredData.forEach(d => {
        const key = d.productName;
        if (!products[key]) products[key] = { plan: 0, actual: 0 };
        products[key].plan += d.planQuantity;
        products[key].actual += d.actualQuantity;
    });

    return Object.entries(products)
        .map(([name, stats]) => ({
            name: name.length > 15 ? name.substring(0, 15) + '...' : name,
            fullName: name,
            plan: stats.plan,
            actual: stats.actual
        }))
        .sort((a, b) => b.plan - a.plan)
        .slice(0, 10);
  }, [filteredData]);

  const handleDelete = (id: string) => {
    if (!window.confirm("Are you sure you want to PERMANENTLY delete this entry?")) return;
    const { deletedItem } = StorageService.deleteProductionEntry(id);
    if (deletedItem) {
        StorageService.addLog({
          userId: user!.id,
          userName: user!.name,
          action: 'DELETE_RECORD',
          details: `Record deleted from reports: ${deletedItem.productName} (${deletedItem.date})`
        });
        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD REMOVED SUCCESSFULLY', type: 'info' } 
        }));
    }
    triggerRefresh();
  };

  const resetFilters = () => {
    setDateRange({ start: '', end: '' });
    setCategory('All');
    setProcessType('All');
    setSortConfig(null);
  };

  const calculateEfficiency = (actual: number, plan: number) => {
    if (!plan || plan === 0) return 0;
    return ((actual / plan) * 100).toFixed(1);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';
    const today = getTodayISO();

    if (viewMode === 'daily') {
        headers = ["Date", "Status Shift", "Category", "Process", "Product", "Plan", "Actual", "Unit", "Efficiency %", "Batch No", "Manpower", "Status", "Plan Remark", "Actual Remark"];
        rows = filteredData.map(d => {
            const isOff = offDays.some(od => od.date === d.date);
            return [
                d.date, isOff ? 'Holiday Shift' : 'Normal', d.category, d.process, `"${d.productName}"`, d.planQuantity || 0, d.actualQuantity || 0, d.unit || 'KG',
                calculateEfficiency(d.actualQuantity || 0, d.planQuantity || 0), d.batchNo || '', Number(d.manpower || 0), d.status || 'In Progress', `"${(d.planRemark || '').replace(/"/g, '""')}"`, `"${(d.actualRemark || '').replace(/"/g, '""')}"`
            ];
        });
        filename = `production_log_daily_${today}.csv`;
    } else {
        headers = ["Month", "Process", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [ m.name, m.process, m.plan || 0, m.actual || 0, (m.efficiency || 0).toFixed(2) ]);
        filename = `production_summary_monthly_${today}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  const SortHeader = ({ label, sortKey, align = 'left' }: { label: string, sortKey: keyof ProductionEntry, align?: 'left' | 'right' | 'center' }) => (
    <th className={`px-8 py-5 cursor-pointer group text-${align}`} onClick={() => handleSort(sortKey)}>
        <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : ''}`}>
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600 dark:text-indigo-400' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100 text-indigo-600 dark:text-indigo-400' : 'opacity-0 group-hover:opacity-60'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-black text-gray-800 dark:text-white">Production Analytics</h2>

        <div className="flex items-center bg-white dark:bg-slate-800 rounded-xl p-1.5 border border-gray-200 dark:border-slate-700 shadow-sm">
            <button onClick={() => setViewMode('daily')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition ${viewMode === 'daily' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500 hover:text-indigo-600'}`}>
                <List className="w-4 h-4" /> Daily
            </button>
            <button onClick={() => setViewMode('monthly')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition ${viewMode === 'monthly' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500 hover:text-indigo-600'}`}>
                <Calendar className="w-4 h-4" /> Monthly
            </button>
        </div>

        <button onClick={downloadCSV} className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-emerald-700 transition shadow-lg shadow-emerald-500/20">
            <Download className="w-4 h-4" /> Export Report
        </button>
      </div>

      {/* FILTER PANEL */}
      <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 shadow-sm border border-gray-100 dark:border-slate-700 flex flex-wrap gap-6 items-end">
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1">
            <Filter className="w-3 h-3" /> Date From
          </label>
          <input 
            type="date" 
            value={dateRange.start} 
            onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))}
            className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 w-full sm:w-auto font-bold dark:text-white"
          />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1">
            <Filter className="w-3 h-3" /> Date To
          </label>
          <input 
            type="date" 
            value={dateRange.end} 
            onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))}
            className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 w-full sm:w-auto font-bold dark:text-white"
          />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Department</label>
          <select 
            value={category} 
            onChange={e => setCategory(e.target.value)}
            className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 min-w-[160px] font-bold dark:text-white"
          >
            <option value="All">All Departments</option>
            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Process</label>
          <select 
            value={processType} 
            onChange={e => setProcessType(e.target.value)}
            className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 min-w-[160px] font-bold dark:text-white"
          >
            <option value="All">All Processes</option>
            {PROCESSES.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
        <button 
          onClick={resetFilters}
          className="flex items-center gap-1.5 px-4 py-2.5 text-[10px] font-black uppercase tracking-widest text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-900/20 rounded-xl transition"
        >
          <XCircle className="w-4 h-4" /> Reset
        </button>
      </div>

      {/* CHART SECTION */}
      <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700">
        <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
                <BarChart2 className="w-5 h-5 text-indigo-500" />
                <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">
                    {viewMode === 'daily' ? 'Filtered Product Performance (Top 10)' : 'Monthly Overall Efficiency'}
                </h3>
            </div>
            {viewMode === 'monthly' && (
                <div className="flex items-center gap-6">
                    <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full bg-indigo-500"></div>
                        <span className="text-[10px] font-black text-slate-400 uppercase">Plan</span>
                    </div>
                    <div className="flex items-center gap-2">
                        <div className="w-3 h-3 rounded-full bg-emerald-500"></div>
                        <span className="text-[10px] font-black text-slate-400 uppercase">Actual</span>
                    </div>
                </div>
            )}
        </div>

        <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={viewMode === 'daily' ? chartDailyData : monthlyChartSummaryData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? '#334155' : '#f1f5f9'} />
                    <XAxis 
                        dataKey="name" 
                        axisLine={false} 
                        tickLine={false} 
                        tick={{ fontSize: 10, fontWeight: 800, fill: isDarkMode ? '#94a3b8' : '#64748b' }} 
                        dy={10}
                    />
                    <YAxis 
                        axisLine={false} 
                        tickLine={false} 
                        tick={{ fontSize: 10, fontWeight: 800, fill: isDarkMode ? '#94a3b8' : '#64748b' }} 
                    />
                    <Tooltip 
                        cursor={{ fill: isDarkMode ? '#1e293b' : '#f8fafc' }}
                        contentStyle={{ 
                            backgroundColor: isDarkMode ? '#1e293b' : '#ffffff', 
                            borderRadius: '16px', 
                            border: 'none', 
                            boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)',
                            fontSize: '12px',
                            fontWeight: 'bold'
                        }}
                    />
                    <Bar dataKey="plan" name="Target Plan" fill="#6366f1" radius={[6, 6, 0, 0]} barSize={viewMode === 'daily' ? 30 : 50} />
                    <Bar dataKey="actual" name="Total Actual" fill="#10b981" radius={[6, 6, 0, 0]} barSize={viewMode === 'daily' ? 30 : 50} />
                    {viewMode === 'monthly' && (
                        <Line type="monotone" dataKey="efficiency" name="Eff. %" stroke="#f59e0b" strokeWidth={3} dot={{ fill: '#f59e0b', r: 4 }} />
                    )}
                </ComposedChart>
            </ResponsiveContainer>
        </div>
      </div>

      {/* DATA TABLE SECTION */}
      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-sm text-left border-collapse">
            <thead className="bg-gray-50/50 dark:bg-slate-900/50 text-slate-400 font-black uppercase text-[10px] tracking-widest border-b dark:border-slate-700">
              {viewMode === 'daily' ? (
                  <tr>
                    <SortHeader label="Production Date" sortKey="date" />
                    <SortHeader label="Dept" sortKey="category" align="center" />
                    <SortHeader label="Product Name" sortKey="productName" />
                    <th className="px-8 py-5 text-right">Plan & Remark</th>
                    <th className="px-8 py-5 text-right">Actual & Remark</th>
                    <th className="px-8 py-5 text-center">Unit</th>
                    <th className="px-8 py-5 text-right">Eff. %</th>
                    <th className="px-8 py-5 text-center">Manpower</th>
                    <SortHeader label="Status" sortKey="status" align="center" />
                    {hasPermission(['admin', 'manager']) && <th className="px-8 py-5 text-center">Actions</th>}
                  </tr>
              ) : (
                  <tr>
                    <th className="px-8 py-5">Summary Month</th>
                    <th className="px-8 py-5">Process Breakdown</th>
                    <th className="px-8 py-5 text-right">Plan Qty</th>
                    <th className="px-8 py-5 text-right">Actual Qty</th>
                    <th className="px-8 py-5 text-right">Efficiency %</th>
                  </tr>
              )}
            </thead>
            <tbody className="divide-y divide-gray-50 dark:divide-slate-700/50">
              {viewMode === 'daily' ? (
                  filteredData.length === 0 ? (
                    <tr>
                      <td colSpan={10} className="px-8 py-20 text-center text-slate-400 font-bold uppercase tracking-widest italic">No matching records found</td>
                    </tr>
                  ) : filteredData.map(entry => {
                    const eff = Number(calculateEfficiency(entry.actualQuantity || 0, entry.planQuantity || 0));
                    const isOff = entry.date && offDays.some(od => od.date === entry.date);
                    const isCompleted = entry.status === 'Completed';
                    return (
                      <tr key={entry.id} className={`hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition-colors ${isOff ? 'bg-amber-50/10 dark:bg-amber-900/5' : ''}`}>
                        <td className="px-8 py-6">
                            <div className="font-black text-slate-800 dark:text-white mb-1 font-mono text-xs">{entry.date || 'N/A'}</div>
                            {isOff ? (
                                <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-amber-600 dark:text-amber-400">
                                    <Palmtree className="w-3 h-3" /> Holiday
                                </span>
                            ) : (
                                <span className="text-[9px] font-black uppercase text-slate-300">Operational</span>
                            )}
                        </td>
                        <td className="px-8 py-6 text-center">
                          <span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-900 text-slate-500 border border-slate-200 dark:border-slate-800">
                            {entry.category}
                          </span>
                        </td>
                        <td className="px-8 py-6">
                            <div className="font-black text-slate-800 dark:text-white">{entry.productName}</div>
                            <span className="text-[10px] font-black uppercase text-indigo-500 tracking-tight">{entry.process}</span>
                        </td>
                        <td className="px-8 py-6 text-right">
                            <div className="font-black font-mono text-slate-700 dark:text-slate-200">{(entry.planQuantity || 0).toLocaleString()}</div>
                            {entry.planRemark && (
                              <div className="flex items-center justify-end gap-1 mt-1">
                                <MessageSquare className="w-2.5 h-2.5 text-slate-300 shrink-0" />
                                <span className="text-[9px] text-slate-400 italic font-medium whitespace-normal text-right max-w-[150px]">{entry.planRemark}</span>
                              </div>
                            )}
                        </td>
                        <td className="px-8 py-6 text-right">
                            <div className="font-black font-mono text-emerald-500">{(entry.actualQuantity || 0).toLocaleString()}</div>
                            {entry.actualRemark && (
                              <div className="flex items-center justify-end gap-1 mt-1">
                                <MessageSquare className="w-2.5 h-2.5 text-emerald-200 shrink-0" />
                                <span className="text-[9px] text-emerald-400 font-medium italic whitespace-normal text-right max-w-[150px]">{entry.actualRemark}</span>
                              </div>
                            )}
                        </td>
                        <td className="px-8 py-6 text-center">
                          <span className="text-[10px] font-black text-slate-400">{entry.unit || 'KG'}</span>
                        </td>
                        <td className="px-8 py-6 text-right">
                            <div className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-xl border font-black text-[11px] ${
                                eff >= 100 ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 
                                eff >= 80 ? 'bg-indigo-50 text-indigo-600 border-indigo-100' : 
                                'bg-rose-50 text-rose-600 border-rose-100'
                            }`}>
                                {eff}%
                            </div>
                        </td>
                        <td className="px-8 py-6 text-center font-black font-mono text-slate-800 dark:text-white">
                          {Number(entry.manpower || 0)}
                        </td>
                        <td className="px-8 py-6 text-center">
                            <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-tight border ${
                                isCompleted ? 'bg-emerald-50 text-emerald-600 border-emerald-200' : 'bg-indigo-50 text-indigo-600 border-indigo-200'
                            }`}>
                                {isCompleted ? <CheckCircle className="w-3 h-3" /> : <Clock className="w-3 h-3 animate-pulse" />}
                                {entry.status || 'In Progress'}
                            </div>
                        </td>
                        {hasPermission(['admin', 'manager']) && (
                            <td className="px-8 py-6 text-center">
                                <button onClick={() => handleDelete(entry.id)} className="text-slate-300 hover:text-rose-500 p-2.5 rounded-xl hover:bg-rose-50 dark:hover:bg-rose-900/20 transition-all">
                                  <Trash2 className="w-4 h-4" />
                                </button>
                            </td>
                        )}
                      </tr>
                    );
                  })
              ) : (
                  monthlyData.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="px-8 py-20 text-center text-slate-400 font-bold uppercase tracking-widest italic">No summaries available</td>
                    </tr>
                  ) : monthlyData.map(m => (
                      <tr key={`${m.name}-${m.process}`} className="hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition">
                          <td className="px-8 py-6 font-black text-slate-800 dark:text-white text-lg">{m.name}</td>
                          <td className="px-8 py-6">
                            <span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border border-indigo-100 dark:border-indigo-800">
                              {m.process}
                            </span>
                          </td>
                          <td className="px-8 py-6 text-right font-mono font-black text-slate-700 dark:text-slate-200">{(m.plan || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-mono font-black text-emerald-500">{(m.actual || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-black">
                            <div className={`inline-flex px-4 py-2 rounded-2xl font-black text-base ${m.efficiency >= 85 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                              {m.efficiency.toFixed(1)}%
                            </div>
                          </td>
                      </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, List, Calendar, 
  Download, Pencil, Trash2, Layers,
  Palmtree, MessageSquare, ArrowUpDown, Clock, CheckCircle
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);

    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;

    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();

    const validProcesses = ['Toothpaste', 'Rocksalt', 'Cosmetic'].includes(category)
      ? PROCESSES.filter(p => p !== 'Encapsulation')
      : [...PROCESSES];

    validProcesses.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);

        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const filteredOffDays = offDays.filter(od => od && od.date && od.date.trim().startsWith(selectedMonth));

    const dates = new Set<string>();
    filteredEntries.forEach(d => {
      if (d.date) dates.add(d.date.trim().substring(0, 10));
    });
    filteredOffDays.forEach(od => {
      if (od.date) dates.add(od.date.trim().substring(0, 10));
    });

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));

    return sortedDates.map(dateKey => {
        let entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);

        // Apply internal sorting if configured
        if (sortConfig) {
            entriesForDate = [...entriesForDate].sort((a, b) => {
                const aValue = (a[sortConfig.key] || '').toString();
                const bValue = (b[sortConfig.key] || '').toString();
                if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
                return 0;
            });
        }

        const offDayInfo = filteredOffDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            isOffDay: !!offDayInfo,
            offDayName: offDayInfo?.description || ''
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth, sortConfig]);

  const handleDelete = (id: string) => {
      if(!window.confirm("Are you sure you want to PERMANENTLY delete this record? This action cannot be undone.")) return;

      const { deletedItem } = StorageService.deleteProductionEntry(id);

      if (deletedItem) {
          StorageService.addLog({
            userId: user!.id,
            userName: user!.name,
            action: 'DELETE_RECORD',
            details: `Admin/Manager/Planner permanently deleted production record: ${deletedItem.productName} (${deletedItem.date})`
          });

          window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: 'RECORD DELETED SUCCESSFULLY', type: 'info' } 
          }));
      }

      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const downloadCSV = () => {
    const headers = ["Date", "Status Shift", "Process", "Product", "Plan", "Actual", "Unit", "Batch No", "Manpower", "Plan Remark", "Actual Remark", "Status"];
    const rows = dailyGroups.flatMap(g => {
        if (g.entries.length === 0) {
            return [[g.date, g.offDayName || 'Off Day', '-', '-', 0, 0, '-', '-', 0, '-', '-', '-']];
        }
        return g.entries.map(d => [
            d.date, g.isOffDay ? `Holiday (${g.offDayName})` : 'Normal', d.process, d.productName, d.planQuantity, d.actualQuantity, d.unit || 'KG', d.batchNo, d.manpower, (d.planRemark || '').replace(/,/g, ';'), (d.actualRemark || '').replace(/,/g, ';'), d.status || 'In Progress'
        ]);
    });
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `Halagel_Full_Report_${category}_${selectedMonth}.csv`);
    document.body.appendChild(link);
    link.click();

    StorageService.addLog({
      userId: user!.id,
      userName: user!.name,
      action: 'EXPORT_REPORT',
      details: `Exported full report for ${category} (${selectedMonth})`
    });

    window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } }));
  };

  const SortHeader = ({ label, sortKey }: { label: string, sortKey: keyof ProductionEntry }) => (
    <th className="px-8 py-4 cursor-pointer group" onClick={() => handleSort(sortKey)}>
        <div className="flex items-center gap-1">
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600 dark:text-indigo-400' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100 text-indigo-600 dark:text-indigo-400' : 'opacity-0 group-hover:opacity-40'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-8 pb-12">
      {/* MONTHLY PROCESS BREAKDOWN */}
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
            <Layers className="w-4 h-4 text-indigo-500" />
            <h3 className="text-[12px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.3em]">Monthly Process Breakdown</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-800 shadow-sm group hover:border-indigo-500/30 transition-all duration-300">
                        <div className="flex items-center justify-between mb-6">
                          <p className="text-sm font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{item.process}</p>
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse" />
                        </div>

                        <div className="space-y-5">
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-tighter">Planned Output</span>
                                <span className="text-2xl font-black text-slate-800 dark:text-white font-mono leading-none">{(item.Plan || 0).toLocaleString()}</span>
                            </div>

                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-tighter">Actual Result</span>
                                <span className="text-2xl font-black text-emerald-500 font-mono leading-none">{(item.Actual || 0).toLocaleString()}</span>
                            </div>

                            <div className="pt-5 border-t border-gray-50 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Efficiency</span>
                                <span className={`text-xl font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(1)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      {/* Daily Logs */}
      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Operational granularity for {selectedMonth}</p>
            </div>

            <div className="flex items-center gap-3">
              <input 
                type="month" 
                value={selectedMonth} 
                onChange={(e) => setSelectedMonth(e.target.value)}
                className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none"
              />
              <button onClick={downloadCSV} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white text-xs font-black rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-500/20 uppercase tracking-widest transition">
                <Download className="w-4 h-4" /> Export Report
              </button>
            </div>
        </div>

        <div className="space-y-6">
            {dailyGroups.length === 0 ? (
                <div className="glass-panel p-16 rounded-[2rem] text-center">
                    <div className="flex flex-col items-center gap-4">
                        <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-full text-slate-200">
                            <ClipboardList className="w-12 h-12" />
                        </div>
                        <p className="text-slate-400 font-bold uppercase tracking-widest">No production logs found for the selected month.</p>
                        <p className="text-xs text-slate-400">Try changing the category or month filter.</p>
                    </div>
                </div>
            ) : dailyGroups.map((group, groupIdx) => {
                const displayDate = formatDisplayDate(group.date);
                const [datePart, dayPart] = displayDate.split(' ');

                return (
                  <div key={`group-${groupIdx}`} className={`bg-white dark:bg-slate-850 rounded-[2rem] overflow-hidden shadow-sm border ${group.isOffDay ? 'border-amber-400/50' : 'border-gray-100 dark:border-slate-800'}`}>
                      <div className={`p-6 flex justify-between items-center border-b ${group.isOffDay ? 'bg-amber-50 dark:bg-amber-900/10 border-amber-100 dark:border-amber-900/30' : 'border-gray-100 dark:border-slate-800 bg-gray-50/50 dark:bg-slate-800/50'}`}>
