            <button onClick={() => setViewMode('monthly')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black transition ${viewMode === 'monthly' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Calendar className="w-4 h-4" /> Monthly</button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 shadow-sm border border-gray-100 dark:border-slate-700 flex flex-wrap gap-6 items-end">
        <div className="space-y-2">
