import { getDbTimestamp } from '../utils/dateUtils';

const KEYS = {
  USERS: 'halagel_users',
  PRODUCTION: 'halagel_production',
  OFF_DAYS: 'halagel_off_days',
  LOGS: 'halagel_activity_logs',
  CURRENT_USER: 'halagel_current_user_session',
};

// Helper to normalize units safely
const normalizeUnit = (u: any): UnitType => {
  if (u === undefined || u === null || u === '') return 'KG';
  const upper = String(u).trim().toUpperCase();
  const validUnits = UNITS as unknown as string[];
  return validUnits.includes(upper) ? (upper as UnitType) : 'KG';
};

// Normalizer for Production Entries - Ensures NO property is ever undefined/null
const normalizeProduction = (data: any): ProductionEntry => {
  if (!data) return {} as ProductionEntry;

  let entry: Partial<ProductionEntry> = {};

  // If data comes from Google Sheets as an array
  if (Array.isArray(data)) {
    entry = {
      id: String(data[0] || Date.now()),
      date: String(data[1] || '').split(' ')[0],
      category: String(data[2] || 'Healthcare') as any,
      process: String(data[3] || 'Mixing') as any,
      productName: String(data[4] || 'Unknown'),
      planQuantity: Number(data[5] || 0),
      actualQuantity: Number(data[6] || 0),
      unit: normalizeUnit(data[7]), // Column H
      batchNo: String(data[8] || ''),
      manpower: Number(data[9] || 0),
      lastUpdatedBy: String(data[10] || ''),
      updatedAt: String(data[11] || getDbTimestamp()),
      remark: String(data[12] || ''),
      planRemark: String(data[13] || ''),
      actualRemark: String(data[14] || ''),
      status: (data[15] as ProductionStatus) || (Number(data[6] || 0) >= Number(data[5] || 1) ? 'Completed' : 'In Progress')
    };
  } else {
    // If data comes from LocalStorage as an object
    entry = {
      ...data,
      id: String(data.id || Date.now()),
      date: String(data.date || '').split(' ')[0],
      productName: String(data.productName || 'Unknown'),
      planQuantity: Number(data.planQuantity || 0),
      actualQuantity: Number(data.actualQuantity || 0),
      unit: normalizeUnit(data.unit),
      manpower: Number(data.manpower || 0),
      batchNo: String(data.batchNo || ''),
      remark: String(data.remark || ''),
      planRemark: String(data.planRemark || ''),
      actualRemark: String(data.actualRemark || ''),
      process: String(data.process || 'Mixing') as any,
      category: String(data.category || 'Healthcare') as any,
      status: data.status || (Number(data.actualQuantity || 0) >= Number(data.planQuantity || 1) ? 'Completed' : 'In Progress'),
      updatedAt: String(data.updatedAt || getDbTimestamp())
    };
  }
  return entry as ProductionEntry;
};

// Normalizer for Activity Logs
const normalizeLog = (data: any): ActivityLog => {
  if (!data) return {} as ActivityLog;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      timestamp: String(data[1] || getDbTimestamp()),
      userId: String(data[2] || ''),
      userName: String(data[3] || 'System'),
      action: String(data[4] || 'LOG'),
      details: String(data[5] || '')
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now()),
    timestamp: String(data.timestamp || getDbTimestamp()),
    userName: String(data.userName || 'Unknown'),
    details: String(data.details || '')
  };
};

// Normalizer for Off Days
const normalizeOffDay = (data: any): OffDay => {
  if (!data) return {} as OffDay;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      date: String(data[1] || '').split(' ')[0],
      description: String(data[2] || 'Holiday'),
      createdBy: String(data[3] || 'System'),
      // Fix: Added missing 'type' property
      type: (data[4] as OffDayType) || 'Off Day'
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now()),
    date: String(data.date || '').split(' ')[0],
    description: String(data.description || 'Holiday'),
    // Fix: Added missing 'type' property
    type: (data.type as OffDayType) || 'Off Day'
  };
};

const init = () => {
  if (!localStorage.getItem(KEYS.USERS)) {
    localStorage.setItem(KEYS.USERS, JSON.stringify(INITIAL_USERS));
  }
  if (!localStorage.getItem(KEYS.OFF_DAYS)) {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(INITIAL_OFF_DAYS));
  }
  if (!localStorage.getItem(KEYS.PRODUCTION)) {
    const seed = generateSeedProductionData().map(p => ({
      ...p,
      status: p.actualQuantity >= p.planQuantity ? 'Completed' : 'In Progress'
    }));
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(seed));
  }
  if (!localStorage.getItem(KEYS.LOGS)) {
    localStorage.setItem(KEYS.LOGS, JSON.stringify([]));
  }
};

init();

export const StorageService = {
  getUsers: (): User[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.USERS) || '[]');
      return Array.isArray(data) ? data : [];
    } catch { return []; }
  },
  saveUsers: (users: User[]) => {
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    GoogleSheetsService.saveData('saveUsers', users);
  },

  getProductionData: (): ProductionEntry[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.PRODUCTION) || '[]');
      return Array.isArray(data) ? data.map(normalizeProduction).filter(p => p.date && p.date.length > 0) : [];
    } catch { return []; }
  },
  saveProductionData: (data: ProductionEntry[]) => {
    const cleaned = data.map(normalizeProduction).filter(p => p.date && p.date.length > 0);
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(cleaned));
    GoogleSheetsService.saveData('saveProduction', cleaned);
  },

  deleteProductionEntry: (id: string): { updatedData: ProductionEntry[], deletedItem: ProductionEntry | null } => {
    try {
      const data = StorageService.getProductionData();
      const targetId = String(id);
      const targetItem = data.find(p => String(p.id) === targetId) || null;
      const updatedData = data.filter(p => String(p.id) !== targetId);
      StorageService.saveProductionData(updatedData);
      return { updatedData, deletedItem: targetId ? targetItem : null };
    } catch (err) {
      console.error("Storage delete error:", err);
      return { updatedData: StorageService.getProductionData(), deletedItem: null };
    }
  },

  getOffDays: (): OffDay[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.OFF_DAYS) || '[]');
      return Array.isArray(data) ? data.map(normalizeOffDay).filter(od => od.date && od.date.length > 0) : [];
    } catch { return []; }
  },
  saveOffDays: (days: OffDay[]) => {
    const cleaned = days.map(normalizeOffDay).filter(od => od.date && od.date.length > 0);
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(cleaned));
    GoogleSheetsService.saveData('saveOffDays', cleaned);
  },

  syncWithSheets: async () => {
    if (!GoogleSheetsService.isEnabled()) return;

    try {
      const results = await Promise.all([
        GoogleSheetsService.fetchData<any[]>('getProduction'),
        GoogleSheetsService.fetchData<any[]>('getOffDays'),
        GoogleSheetsService.fetchData<any[]>('getLogs'),
        GoogleSheetsService.fetchData<User[]>('getUsers')
      ]);

      if (results[0] && Array.isArray(results[0])) {
          const cleaned = results[0].map(normalizeProduction).filter(p => p.date && p.date.length > 0);
          localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(cleaned));
      }

      if (results[1] && Array.isArray(results[1])) {
          const cleaned = results[1].map(normalizeOffDay).filter(od => od.date && od.date.length > 0);
          localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(cleaned));
      }

      if (results[2] && Array.isArray(results[2])) {
          const cleanedLogs = results[2].map(normalizeLog).filter(l => l.timestamp);
          localStorage.setItem(KEYS.LOGS, JSON.stringify(cleanedLogs));
      }

      if (results[3] && Array.isArray(results[3])) {
          localStorage.setItem(KEYS.USERS, JSON.stringify(results[3]));
      }
    } catch (err) {
      console.error("Critical Sync Failure:", err);
      throw err;
    }
  },

  getLogs: (): ActivityLog[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]');
      return Array.isArray(data) ? data.map(normalizeLog) : [];
    } catch { return []; }
  },
  addLog: (log: Omit<ActivityLog, 'id' | 'timestamp'>) => {
    try {
      const logs = StorageService.getLogs();
      const newLog: ActivityLog = {
        ...log,
        id: Date.now().toString(),
        timestamp: getDbTimestamp(),
      };
      logs.unshift(newLog);
      if (logs.length > 500) logs.pop(); 

      localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
      GoogleSheetsService.saveData('saveLogs', logs);
    } catch (err) {
      console.error("Logging error:", err);
    }
  },

  getSession: (): User | null => {
    try {
      const session = localStorage.getItem(KEYS.CURRENT_USER);
      return session ? JSON.parse(session) : null;
    } catch { return null; }
  },
  setSession: (user: User | null) => {
    if (user) localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    else localStorage.removeItem(KEYS.CURRENT_USER);
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, ProductionStatus } from '../../types';
import { Trash2, Download, Calendar, List, Filter, XCircle, Palmtree, BarChart2, MessageSquare, ArrowUpDown, Clock, CheckCircle, ShieldAlert } from 'lucide-react';
import { getTodayISO, isWeeklyRestDay } from '../../utils/dateUtils';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, 
  ResponsiveContainer, LineChart, Line, AreaChart, Area, ComposedChart,
  Cell
} from 'recharts';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const ProductionLog: React.FC = () => {
  const { user, hasPermission } = useAuth();
  const { refreshKey, triggerRefresh, isDarkMode } = useDashboard();
  const [data, setData] = useState<ProductionEntry[]>([]);
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);
  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [category, setCategory] = useState('All');
  const [processType, setProcessType] = useState('All');
  const [statusFilter, setStatusFilter] = useState('All');

  useEffect(() => {
    setData(StorageService.getProductionData());
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const filteredData = useMemo(() => {
    let result = data.filter(d => {
      if (!d) return false;
      const matchCat = category === 'All' || d.category === category;
      const matchProc = processType === 'All' || d.process === processType;
      const matchStatus = statusFilter === 'All' || d.status === statusFilter;
      const matchStart = !dateRange.start || (d.date && d.date >= dateRange.start);
      const matchEnd = !dateRange.end || (d.date && d.date <= dateRange.end);
      return matchCat && matchProc && matchStatus && matchStart && matchEnd;
    });

    const statusWeight: Record<string, number> = { 'In Progress': 1, 'Completed': 2 };

    if (sortConfig) {
        result = [...result].sort((a, b) => {
            let aVal: any = a[sortConfig.key];
            let bVal: any = b[sortConfig.key];
            if (sortConfig.key === 'status') {
                aVal = statusWeight[a.status as ProductionStatus] || 0;
                bVal = statusWeight[b.status as ProductionStatus] || 0;
            } else {
                aVal = (aVal || '').toString();
                bVal = (bVal || '').toString();
            }
            if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
    } else {
        result.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    }

    return result;
  }, [data, dateRange, category, processType, statusFilter, sortConfig]);

  const monthlyData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number, count: number, month: string, process: string }> = {};
    filteredData.forEach(d => {
        if (!d.date) return;
        const monthKey = d.date.substring(0, 7); 
        const procKey = d.process || 'Other';
        const compositeKey = `${monthKey}_${procKey}`;
        if (!groups[compositeKey]) {
            groups[compositeKey] = { plan: 0, actual: 0, count: 0, month: monthKey, process: procKey };
        }
        groups[compositeKey].plan += (d.planQuantity || 0);
        groups[compositeKey].actual += (d.actualQuantity || 0);
        groups[compositeKey].count++;
    });
    return Object.values(groups).map((stats) => ({
        name: stats.month, process: stats.process, plan: stats.plan, actual: stats.actual,
        efficiency: stats.plan > 0 ? Number(((stats.actual / stats.plan) * 100).toFixed(1)) : 0
    })).sort((a, b) => b.name.localeCompare(a.name)); 
  }, [filteredData]);

  const monthlyChartSummaryData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number }> = {};
    filteredData.forEach(d => {
      if (!d.date) return;
      const monthKey = d.date.substring(0, 7);
      if (!groups[monthKey]) groups[monthKey] = { plan: 0, actual: 0 };
      groups[monthKey].plan += (d.planQuantity || 0);
      groups[monthKey].actual += (d.actualQuantity || 0);
    });
    return Object.entries(groups).map(([month, stats]) => ({
        name: month, plan: stats.plan, actual: stats.actual,
        efficiency: stats.plan > 0 ? Number(((stats.actual / stats.plan) * 100).toFixed(1)) : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
  }, [filteredData]);

  const chartDailyData = useMemo(() => {
    const products: Record<string, { plan: number, actual: number }> = {};
    filteredData.forEach(d => {
        const key = d.productName;
        if (!products[key]) products[key] = { plan: 0, actual: 0 };
        products[key].plan += d.planQuantity;
        products[key].actual += d.actualQuantity;
    });
    return Object.entries(products).map(([name, stats]) => ({
        name: name.length > 15 ? name.substring(0, 15) + '...' : name,
        fullName: name, plan: stats.plan, actual: stats.actual
    })).sort((a, b) => b.plan - a.plan).slice(0, 10);
  }, [filteredData]);

  const calculateEfficiency = (actual: number, plan: number) => plan > 0 ? ((actual / plan) * 100).toFixed(1) : '0';

  const resetFilters = () => {
    setDateRange({ start: '', end: '' });
    setCategory('All');
    setProcessType('All');
    setStatusFilter('All');
    setSortConfig(null);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';
    const today = getTodayISO();

    if (viewMode === 'daily') {
        headers = ["Date", "Category", "Process", "Product", "Plan", "Actual", "Unit", "Efficiency %", "Batch No", "Manpower", "Status", "Plan Remark", "Actual Remark"];
        rows = filteredData.map(d => [
            d.date, d.category, d.process, `"${d.productName}"`, d.planQuantity || 0, d.actualQuantity || 0, d.unit || 'KG',
            calculateEfficiency(d.actualQuantity || 0, d.planQuantity || 0), d.batchNo || '', Number(d.manpower || 0), d.status || 'In Progress', 
            `"${(d.planRemark || '').replace(/"/g, '""')}"`, `"${(d.actualRemark || '').replace(/"/g, '""')}"`
        ]);
        filename = `production_log_daily_${today}.csv`;
    } else {
        headers = ["Month", "Process", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [ m.name, m.process, m.plan || 0, m.actual || 0, (m.efficiency || 0).toFixed(2) ]);
        filename = `production_summary_monthly_${today}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } 
    }));
  };

  const SortHeader = ({ label, sortKey, align = 'left' }: { label: string, sortKey: keyof ProductionEntry, align?: 'left' | 'right' | 'center' }) => (
    <th className={`px-8 py-5 cursor-pointer group text-${align}`} onClick={() => handleSort(sortKey)}>
        <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : ''}`}>
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100' : 'opacity-0 group-hover:opacity-60'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-black text-gray-800 dark:text-white">Production Analytics</h2>

        <div className="flex items-center gap-4">
          <div className="flex items-center bg-white dark:bg-slate-800 rounded-xl p-1.5 border border-gray-200 dark:border-slate-700 shadow-sm">
              <button onClick={() => setViewMode('daily')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black transition ${viewMode === 'daily' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500'}`}><List className="w-4 h-4" /> Daily</button>
              <button onClick={() => setViewMode('monthly')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black transition ${viewMode === 'monthly' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500'}`}><Calendar className="w-4 h-4" /> Monthly</button>
          </div>

          <button 
            onClick={downloadCSV} 
            className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-emerald-700 transition shadow-lg shadow-emerald-500/20"
          >
            <Download className="w-4 h-4" /> Export Report
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 shadow-sm border border-gray-100 dark:border-slate-700 flex flex-wrap gap-6 items-end">
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Date From</label>
          <input type="date" value={dateRange.start} onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold" />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Date To</label>
          <input type="date" value={dateRange.end} onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold" />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Status</label>
          <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold">
            <option value="All">All Statuses</option>
            <option value="In Progress">In Progress</option>
            <option value="Completed">Completed</option>
          </select>
        </div>
        <button onClick={resetFilters} className="flex items-center gap-1.5 px-4 py-2.5 text-[10px] font-black uppercase text-rose-500 hover:bg-rose-50 rounded-xl transition"><XCircle className="w-4 h-4" /> Reset</button>
      </div>

      <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700">
        <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={viewMode === 'daily' ? chartDailyData : monthlyChartSummaryData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? '#334155' : '#f1f5f9'} />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 800, fill: '#94a3b8' }} dy={10} />
                    <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 800, fill: '#94a3b8' }} />
                    <Tooltip contentStyle={{ backgroundColor: isDarkMode ? '#1e293b' : '#fff', borderRadius: '16px', border: 'none', fontSize: '12px', fontWeight: 'bold' }} />
                    <Bar dataKey="plan" name="Target Plan" fill="#6366f1" radius={[6, 6, 0, 0]} barSize={viewMode === 'daily' ? 30 : 50} />
                    <Bar dataKey="actual" name="Total Actual" fill="#10b981" radius={[6, 6, 0, 0]} barSize={viewMode === 'daily' ? 30 : 50} />
                    {viewMode === 'monthly' && <Line type="monotone" dataKey="efficiency" name="Eff. %" stroke="#f59e0b" strokeWidth={3} />}
                </ComposedChart>
            </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-sm text-left border-collapse">
            <thead className="bg-gray-50/50 dark:bg-slate-900/50 text-slate-400 font-black uppercase text-[10px] tracking-widest border-b dark:border-slate-700">
              {viewMode === 'daily' ? (
                  <tr>
                    <SortHeader label="Date" sortKey="date" />
                    <SortHeader label="Dept" sortKey="category" align="center" />
                    <SortHeader label="Product" sortKey="productName" />
                    <th className="px-8 py-5 text-right">Plan</th>
                    <th className="px-8 py-5 text-right">Actual</th>
                    <th className="px-8 py-5 text-right">Eff. %</th>
                    <SortHeader label="Status" sortKey="status" align="center" />
                  </tr>
              ) : (
                  <tr>
                    <th className="px-8 py-5">Month</th>
                    <th className="px-8 py-5">Process</th>
                    <th className="px-8 py-5 text-right">Plan</th>
                    <th className="px-8 py-5 text-right">Actual</th>
                    <th className="px-8 py-5 text-right">Efficiency %</th>
                  </tr>
              )}
            </thead>
            <tbody className="divide-y divide-gray-50 dark:divide-slate-700/50">
              {viewMode === 'daily' ? (
                  filteredData.map(entry => {
                    const eff = Number(calculateEfficiency(entry.actualQuantity || 0, entry.planQuantity || 0));
                    const isHol = offDays.some(od => od.date === entry.date);
                    const isRest = isWeeklyRestDay(entry.date);
                    return (
                      <tr key={entry.id} className={`hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition-colors ${(isHol || isRest) ? 'bg-amber-50/10' : ''}`}>
                        <td className="px-8 py-6">
                            <div className="font-black text-slate-800 dark:text-white font-mono text-xs">{entry.date}</div>
                            {isHol ? <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-amber-600"><Palmtree className="w-3 h-3" /> Holiday</span> 
                             : isRest ? <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-indigo-500"><ShieldAlert className="w-3 h-3" /> Rest Day</span>
                             : <span className="text-[9px] font-black uppercase text-slate-300">Operational</span>}
                        </td>
                        <td className="px-8 py-6 text-center">
                          <span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-900 text-slate-500 border dark:border-slate-800">{entry.category}</span>
                        </td>
                        <td className="px-8 py-6"><div className="font-black text-slate-800 dark:text-white">{entry.productName}</div></td>
                        <td className="px-8 py-6 text-right font-black font-mono text-slate-700 dark:text-slate-200">{(entry.planQuantity || 0).toLocaleString()}</td>
                        <td className="px-8 py-6 text-right font-black font-mono text-emerald-500">{(entry.actualQuantity || 0).toLocaleString()}</td>
                        <td className="px-8 py-6 text-right font-black">{eff}%</td>
                        <td className="px-8 py-6 text-center">
                            <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[9px] font-black uppercase border ${entry.status === 'Completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                                {entry.status === 'Completed' ? <CheckCircle className="w-3 h-3" /> : <Clock className="w-3 h-3 animate-pulse" />} {entry.status}
                            </div>
                        </td>
                      </tr>
                    );
                  })
              ) : (
                  monthlyData.map(m => (
                      <tr key={`${m.name}-${m.process}`} className="hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition">
                          <td className="px-8 py-6 font-black text-slate-800 dark:text-white text-lg">{m.name}</td>
                          <td className="px-8 py-6"><span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border border-indigo-100">{m.process}</span></td>
                          <td className="px-8 py-6 text-right font-mono font-black text-slate-700 dark:text-slate-200">{(m.plan || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-mono font-black text-emerald-500">{(m.actual || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-black"><div className={`inline-flex px-4 py-2 rounded-2xl font-black text-base ${m.efficiency >= 85 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>{m.efficiency.toFixed(1)}%</div></td>
                      </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { OffDay } from '../../types';
import { Trash2, Plus } from 'lucide-react';

export const OffDays: React.FC = () => {
  const { user } = useAuth();
  const [offDays, setOffDays] = useState<OffDay[]>(StorageService.getOffDays());
  const [newDate, setNewDate] = useState('');
  const [description, setDescription] = useState('');

  const handleAdd = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDate) return;

    if (offDays.some(d => d.date === newDate)) {
        alert('Date already marked as off day');
        return;
    }

    // Fix: Added missing 'type' property
    const newOffDay: OffDay = {
        id: Date.now().toString(),
        date: newDate,
        description: description || 'Scheduled Off',
        type: 'Off Day',
        createdBy: user!.id
    };

    const updated = [...offDays, newOffDay].sort((a,b) => a.date.localeCompare(b.date));
    StorageService.saveOffDays(updated);
    setOffDays(updated);
    setNewDate('');
    setDescription('');
  };

  const handleRemove = (id: string) => {
    const updated = offDays.filter(d => d.id !== id);
    StorageService.saveOffDays(updated);
    setOffDays(updated);
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="md:col-span-1 bg-white p-6 rounded-xl shadow-sm border border-gray-100 h-fit">
            <h3 className="text-lg font-bold text-gray-800 mb-4">Add Off Day</h3>
            <form onSubmit={handleAdd} className="space-y-4">
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
                    <input 
                        type="date" 
                        required
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg"
                        value={newDate}
                        onChange={e => setNewDate(e.target.value)}
                    />
                </div>
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
                    <input 
                        type="text" 
                        placeholder="e.g. National Holiday"
                        className="w-full px-4 py-2 border border-gray-300 rounded-lg"
                        value={description}
                        onChange={e => setDescription(e.target.value)}
                    />
                </div>
                <button 
                    type="submit"
                    className="w-full bg-slate-800 text-white py-2 rounded-lg flex items-center justify-center gap-2 hover:bg-slate-700"
                >
                    <Plus className="w-4 h-4" /> Add Date
                </button>
            </form>
        </div>

        <div className="md:col-span-2 bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="p-6 border-b border-gray-100">
                <h3 className="text-lg font-bold text-gray-800">Scheduled Off Days</h3>
            </div>
            <ul className="divide-y divide-gray-100">
                {offDays.length === 0 ? (
                    <li className="p-6 text-gray-400 text-center">No off days scheduled.</li>
                ) : offDays.map(day => (
                    <li key={day.id} className="p-4 flex items-center justify-between hover:bg-gray-50">
                        <div className="flex items-center space-x-4">
                            <div className="bg-red-50 text-red-600 px-3 py-1 rounded-md font-mono text-sm font-bold">
                                {day.date}
                            </div>
                            <span className="text-gray-700 font-medium">{day.description}</span>
                        </div>
                        <button 
                            // Fix: Passing day.id instead of undefined id
                            onClick={() => handleRemove(day.id)}
                            className="text-gray-400 hover:text-red-500 transition-colors"
                        >
                            <Trash2 className="w-5 h-5" />
                        </button>
                    </li>
                ))}
            </ul>
        </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, ProductionStatus } from '../../types';
import { Trash2, Download, Calendar, List, Filter, XCircle, Palmtree, BarChart2, MessageSquare, ArrowUpDown, Clock, CheckCircle, ShieldAlert } from 'lucide-react';
import { getTodayISO, isWeeklyRestDay } from '../../utils/dateUtils';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, 
  ResponsiveContainer, LineChart, Line, AreaChart, Area, ComposedChart,
  Cell
} from 'recharts';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const ProductionLog: React.FC = () => {
  const { user, hasPermission } = useAuth();
  const { refreshKey, triggerRefresh, isDarkMode } = useDashboard();
  const [data, setData] = useState<ProductionEntry[]>([]);
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);
  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [category, setCategory] = useState('All');
  const [processType, setProcessType] = useState('All');
  const [statusFilter, setStatusFilter] = useState('All');

  useEffect(() => {
    setData(StorageService.getProductionData());
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const filteredData = useMemo(() => {
    let result = data.filter(d => {
      if (!d) return false;
      const matchCat = category === 'All' || d.category === category;
      const matchProc = processType === 'All' || d.process === processType;
      const matchStatus = statusFilter === 'All' || d.status === statusFilter;
      const matchStart = !dateRange.start || (d.date && d.date >= dateRange.start);
      const matchEnd = !dateRange.end || (d.date && d.date <= dateRange.end);
      return matchCat && matchProc && matchStatus && matchStart && matchEnd;
    });

    const statusWeight: Record<string, number> = { 'In Progress': 1, 'Completed': 2 };

    if (sortConfig) {
        result = [...result].sort((a, b) => {
            let aVal: any = a[sortConfig.key];
            let bVal: any = b[sortConfig.key];
            if (sortConfig.key === 'status') {
                aVal = statusWeight[a.status as ProductionStatus] || 0;
                bVal = statusWeight[b.status as ProductionStatus] || 0;
            } else {
                aVal = (aVal || '').toString();
                bVal = (bVal || '').toString();
            }
            if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
    } else {
        result.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    }

    return result;
  }, [data, dateRange, category, processType, statusFilter, sortConfig]);

  const monthlyData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number, count: number, month: string, process: string }> = {};
    filteredData.forEach(d => {
        if (!d.date) return;
        const monthKey = d.date.substring(0, 7); 
        const procKey = d.process || 'Other';
        const compositeKey = `${monthKey}_${procKey}`;
        if (!groups[compositeKey]) {
            groups[compositeKey] = { plan: 0, actual: 0, count: 0, month: monthKey, process: procKey };
        }
        groups[compositeKey].plan += (d.planQuantity || 0);
        groups[compositeKey].actual += (d.actualQuantity || 0);
        groups[compositeKey].count++;
    });
    return Object.values(groups).map((stats) => ({
        name: stats.month, process: stats.process, plan: stats.plan, actual: stats.actual,
        efficiency: stats.plan > 0 ? Number(((stats.actual / stats.plan) * 100).toFixed(1)) : 0
    })).sort((a, b) => b.name.localeCompare(a.name)); 
  }, [filteredData]);

  const monthlyChartSummaryData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number }> = {};
    filteredData.forEach(d => {
      if (!d.date) return;
      const monthKey = d.date.substring(0, 7);
      if (!groups[monthKey]) groups[monthKey] = { plan: 0, actual: 0 };
      groups[monthKey].plan += (d.planQuantity || 0);
      groups[monthKey].actual += (d.actualQuantity || 0);
    });
    return Object.entries(groups).map(([month, stats]) => ({
        name: month, plan: stats.plan, actual: stats.actual,
        efficiency: stats.plan > 0 ? Number(((stats.actual / stats.plan) * 100).toFixed(1)) : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
  }, [filteredData]);

  const chartDailyData = useMemo(() => {
    const products: Record<string, { plan: number, actual: number }> = {};
    filteredData.forEach(d => {
        const key = d.productName;
        if (!products[key]) products[key] = { plan: 0, actual: 0 };
        products[key].plan += d.planQuantity;
        products[key].actual += d.actualQuantity;
    });
    return Object.entries(products).map(([name, stats]) => ({
        name: name.length > 15 ? name.substring(0, 15) + '...' : name,
        fullName: name, plan: stats.plan, actual: stats.actual
    })).sort((a, b) => b.plan - a.plan).slice(0, 10);
  }, [filteredData]);

  const calculateEfficiency = (actual: number, plan: number) => plan > 0 ? ((actual / plan) * 100).toFixed(1) : '0';

  const resetFilters = () => {
    setDateRange({ start: '', end: '' });
    setCategory('All');
    setProcessType('All');
    setStatusFilter('All');
    setSortConfig(null);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';
    const today = getTodayISO();

    if (viewMode === 'daily') {
        headers = ["Date", "Category", "Process", "Product", "Plan", "Actual", "Unit", "Efficiency %", "Batch No", "Manpower", "Status", "Plan Remark", "Actual Remark"];
        rows = filteredData.map(d => [
            d.date, d.category, d.process, `"${d.productName}"`, d.planQuantity || 0, d.actualQuantity || 0, d.unit || 'KG',
            calculateEfficiency(d.actualQuantity || 0, d.planQuantity || 0), d.batchNo || '', Number(d.manpower || 0), d.status || 'In Progress', 
            `"${(d.planRemark || '').replace(/"/g, '""')}"`, `"${(d.actualRemark || '').replace(/"/g, '""')}"`
        ]);
        filename = `production_log_daily_${today}.csv`;
    } else {
        headers = ["Month", "Process", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [ m.name, m.process, m.plan || 0, m.actual || 0, (m.efficiency || 0).toFixed(2) ]);
        filename = `production_summary_monthly_${today}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } 
    }));
  };

  const SortHeader = ({ label, sortKey, align = 'left' }: { label: string, sortKey: keyof ProductionEntry, align?: 'left' | 'right' | 'center' }) => (
    <th className={`px-8 py-5 cursor-pointer group text-${align}`} onClick={() => handleSort(sortKey)}>
        <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : ''}`}>
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100' : 'opacity-0 group-hover:opacity-60'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-black text-gray-800 dark:text-white">Production Analytics</h2>

        <div className="flex items-center gap-4">
          <div className="flex items-center bg-white dark:bg-slate-800 rounded-xl p-1.5 border border-gray-200 dark:border-slate-700 shadow-sm">
              <button onClick={() => setViewMode('daily')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black transition ${viewMode === 'daily' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500'}`}><List className="w-4 h-4" /> Daily</button>
              <button onClick={() => setViewMode('monthly')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black transition ${viewMode === 'monthly' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500'}`}><Calendar className="w-4 h-4" /> Monthly</button>
          </div>

          <button 
            onClick={downloadCSV} 
            className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-emerald-700 transition shadow-lg shadow-emerald-500/20"
          >
            <Download className="w-4 h-4" /> Export Report
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 shadow-sm border border-gray-100 dark:border-slate-700 flex flex-wrap gap-6 items-end">
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Date From</label>
          <input type="date" value={dateRange.start} onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold" />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Date To</label>
          <input type="date" value={dateRange.end} onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold" />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Status</label>
          <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold w-full md:w-auto">
            <option value="All">All Statuses</option>
            <option value="In Progress">In Progress</option>
            <option value="Completed">Completed</option>
          </select>
        </div>
        <button onClick={resetFilters} className="flex items-center gap-1.5 px-4 py-2.5 text-[10px] font-black uppercase text-rose-500 hover:bg-rose-50 rounded-xl transition"><XCircle className="w-4 h-4" /> Reset</button>
      </div>

      <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700">
        <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={viewMode === 'daily' ? chartDailyData : monthlyChartSummaryData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? '#334155' : '#f1f5f9'} />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 800, fill: '#94a3b8' }} dy={10} />
                    <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 800, fill: '#94a3b8' }} />
                    <Tooltip contentStyle={{ backgroundColor: isDarkMode ? '#1e293b' : '#fff', borderRadius: '16px', border: 'none', fontSize: '12px', fontWeight: 'bold' }} />
                    <Bar dataKey="plan" name="Target Plan" fill="#6366f1" radius={[6, 6, 0, 0]} barSize={viewMode === 'daily' ? 30 : 50} />
                    <Bar dataKey="actual" name="Total Actual" fill="#10b981" radius={[6, 6, 0, 0]} barSize={viewMode === 'daily' ? 30 : 50} />
                    {viewMode === 'monthly' && <Line type="monotone" dataKey="efficiency" name="Eff. %" stroke="#f59e0b" strokeWidth={3} />}
                </ComposedChart>
            </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-sm text-left border-collapse">
            <thead className="bg-gray-50/50 dark:bg-slate-900/50 text-slate-400 font-black uppercase text-[10px] tracking-widest border-b dark:border-slate-700">
              {viewMode === 'daily' ? (
                  <tr>
                    <SortHeader label="Date" sortKey="date" />
                    <SortHeader label="Dept" sortKey="category" align="center" />
                    <SortHeader label="Product" sortKey="productName" />
                    <th className="px-8 py-5 text-right">Plan</th>
                    <th className="px-8 py-5 text-right">Actual</th>
                    <th className="px-8 py-5 text-right">Eff. %</th>
                    <SortHeader label="Status" sortKey="status" align="center" />
                  </tr>
              ) : (
                  <tr>
                    <th className="px-8 py-5">Month</th>
                    <th className="px-8 py-5">Process</th>
                    <th className="px-8 py-5 text-right">Plan</th>
                    <th className="px-8 py-5 text-right">Actual</th>
                    <th className="px-8 py-5 text-right">Efficiency %</th>
                  </tr>
              )}
            </thead>
            <tbody className="divide-y divide-gray-50 dark:divide-slate-700/50">
              {viewMode === 'daily' ? (
                  filteredData.map(entry => {
                    const eff = Number(calculateEfficiency(entry.actualQuantity || 0, entry.planQuantity || 0));
                    const isHol = offDays.some(od => od.date === entry.date);
                    const isRest = isWeeklyRestDay(entry.date);
                    return (
                      <tr key={entry.id} className={`hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition-colors ${(isHol || isRest) ? 'bg-amber-50/10' : ''}`}>
                        <td className="px-8 py-6">
                            <div className="font-black text-slate-800 dark:text-white font-mono text-xs">{entry.date}</div>
                            {isHol ? <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-amber-600"><Palmtree className="w-3 h-3" /> Holiday</span> 
                             : isRest ? <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-indigo-500"><ShieldAlert className="w-3 h-3" /> Rest Day</span>
                             : <span className="text-[9px] font-black uppercase text-slate-300">Operational</span>}
                        </td>
                        <td className="px-8 py-6 text-center">
                          <span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-900 text-slate-500 border dark:border-slate-800">{entry.category}</span>
                        </td>
                        <td className="px-8 py-6"><div className="font-black text-slate-800 dark:text-white">{entry.productName}</div></td>
                        <td className="px-8 py-6 text-right font-black font-mono text-slate-700 dark:text-slate-200">{(entry.planQuantity || 0).toLocaleString()}</td>
                        <td className="px-8 py-6 text-right font-black font-mono text-emerald-500">{(entry.actualQuantity || 0).toLocaleString()}</td>
                        <td className="px-8 py-6 text-right font-black">{eff}%</td>
                        <td className="px-8 py-6 text-center">
                            <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[9px] font-black uppercase border ${entry.status === 'Completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                                {entry.status === 'Completed' ? <CheckCircle className="w-3 h-3" /> : <Clock className="w-3 h-3 animate-pulse" />} {entry.status}
                            </div>
                        </td>
                      </tr>
                    );
                  })
              ) : (
                  monthlyData.map(m => (
                      <tr key={`${m.name}-${m.process}`} className="hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition">
                          <td className="px-8 py-6 font-black text-slate-800 dark:text-white text-lg">{m.name}</td>
                          <td className="px-8 py-6"><span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border border-indigo-100">{m.process}</span></td>
                          <td className="px-8 py-6 text-right font-mono font-black text-slate-700 dark:text-slate-200">{(m.plan || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-mono font-black text-emerald-500">{(m.actual || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-black"><div className={`inline-flex px-4 py-2 rounded-2xl font-black text-base ${m.efficiency >= 85 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>{m.efficiency.toFixed(1)}%</div></td>
                      </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { StorageService } from '../../services/storageService';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { CATEGORIES, PROCESSES } from '../../constants';
import { ProductionEntry, ProductionStatus } from '../../types';
import { Trash2, Download, Calendar, List, Filter, XCircle, Palmtree, BarChart2, MessageSquare, ArrowUpDown, Clock, CheckCircle, ShieldAlert } from 'lucide-react';
import { getTodayISO, isWeeklyRestDay } from '../../utils/dateUtils';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, 
  ResponsiveContainer, LineChart, Line, AreaChart, Area, ComposedChart,
  Cell
} from 'recharts';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const ProductionLog: React.FC = () => {
  const { user, hasPermission } = useAuth();
  const { refreshKey, triggerRefresh, isDarkMode } = useDashboard();
  const [data, setData] = useState<ProductionEntry[]>([]);
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);
  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const [viewMode, setViewMode] = useState<'daily' | 'monthly'>('daily');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [category, setCategory] = useState('All');
  const [processType, setProcessType] = useState('All');
  const [statusFilter, setStatusFilter] = useState('All');

  useEffect(() => {
    setData(StorageService.getProductionData());
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const filteredData = useMemo(() => {
    let result = data.filter(d => {
      if (!d) return false;
      const matchCat = category === 'All' || d.category === category;
      const matchProc = processType === 'All' || d.process === processType;
      const matchStatus = statusFilter === 'All' || d.status === statusFilter;
      const matchStart = !dateRange.start || (d.date && d.date >= dateRange.start);
      const matchEnd = !dateRange.end || (d.date && d.date <= dateRange.end);
      return matchCat && matchProc && matchStatus && matchStart && matchEnd;
    });

    const statusWeight: Record<string, number> = { 'In Progress': 1, 'Completed': 2 };

    if (sortConfig) {
        result = [...result].sort((a, b) => {
            let aVal: any = a[sortConfig.key];
            let bVal: any = b[sortConfig.key];
            if (sortConfig.key === 'status') {
                aVal = statusWeight[a.status as ProductionStatus] || 0;
                bVal = statusWeight[b.status as ProductionStatus] || 0;
            } else {
                aVal = (aVal || '').toString();
                bVal = (bVal || '').toString();
            }
            if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
            if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
            return 0;
        });
    } else {
        result.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
    }

    return result;
  }, [data, dateRange, category, processType, statusFilter, sortConfig]);

  const monthlyData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number, count: number, month: string, process: string }> = {};
    filteredData.forEach(d => {
        if (!d.date) return;
        const monthKey = d.date.substring(0, 7); 
        const procKey = d.process || 'Other';
        const compositeKey = `${monthKey}_${procKey}`;
        if (!groups[compositeKey]) {
            groups[compositeKey] = { plan: 0, actual: 0, count: 0, month: monthKey, process: procKey };
        }
        groups[compositeKey].plan += (d.planQuantity || 0);
        groups[compositeKey].actual += (d.actualQuantity || 0);
        groups[compositeKey].count++;
    });
    return Object.values(groups).map((stats) => ({
        name: stats.month, process: stats.process, plan: stats.plan, actual: stats.actual,
        efficiency: stats.plan > 0 ? Number(((stats.actual / stats.plan) * 100).toFixed(1)) : 0
    })).sort((a, b) => b.name.localeCompare(a.name)); 
  }, [filteredData]);

  const monthlyChartSummaryData = useMemo(() => {
    const groups: Record<string, { plan: number, actual: number }> = {};
    filteredData.forEach(d => {
      if (!d.date) return;
      const monthKey = d.date.substring(0, 7);
      if (!groups[monthKey]) groups[monthKey] = { plan: 0, actual: 0 };
      groups[monthKey].plan += (d.planQuantity || 0);
      groups[monthKey].actual += (d.actualQuantity || 0);
    });
    return Object.entries(groups).map(([month, stats]) => ({
        name: month, plan: stats.plan, actual: stats.actual,
        efficiency: stats.plan > 0 ? Number(((stats.actual / stats.plan) * 100).toFixed(1)) : 0
    })).sort((a, b) => a.name.localeCompare(b.name));
  }, [filteredData]);

  const chartDailyData = useMemo(() => {
    const products: Record<string, { plan: number, actual: number }> = {};
    filteredData.forEach(d => {
        const key = d.productName;
        if (!products[key]) products[key] = { plan: 0, actual: 0 };
        products[key].plan += d.planQuantity;
        products[key].actual += d.actualQuantity;
    });
    return Object.entries(products).map(([name, stats]) => ({
        name: name.length > 15 ? name.substring(0, 15) + '...' : name,
        fullName: name, plan: stats.plan, actual: stats.actual
    })).sort((a, b) => b.plan - a.plan).slice(0, 10);
  }, [filteredData]);

  const calculateEfficiency = (actual: number, plan: number) => plan > 0 ? ((actual / plan) * 100).toFixed(1) : '0';

  const resetFilters = () => {
    setDateRange({ start: '', end: '' });
    setCategory('All');
    setProcessType('All');
    setStatusFilter('All');
    setSortConfig(null);
  };

  const downloadCSV = () => {
    let headers: string[] = [];
    let rows: (string | number)[][] = [];
    let filename = '';
    const today = getTodayISO();

    if (viewMode === 'daily') {
        headers = ["Date", "Category", "Process", "Product", "Plan", "Actual", "Unit", "Efficiency %", "Batch No", "Manpower", "Status", "Plan Remark", "Actual Remark"];
        rows = filteredData.map(d => [
            d.date, d.category, d.process, `"${d.productName}"`, d.planQuantity || 0, d.actualQuantity || 0, d.unit || 'KG',
            calculateEfficiency(d.actualQuantity || 0, d.planQuantity || 0), d.batchNo || '', Number(d.manpower || 0), d.status || 'In Progress', 
            `"${(d.planRemark || '').replace(/"/g, '""')}"`, `"${(d.actualRemark || '').replace(/"/g, '""')}"`
        ]);
        filename = `production_log_daily_${today}.csv`;
    } else {
        headers = ["Month", "Process", "Total Plan", "Total Actual", "Overall Efficiency %"];
        rows = monthlyData.map(m => [ m.name, m.process, m.plan || 0, m.actual || 0, (m.efficiency || 0).toFixed(2) ]);
        filename = `production_summary_monthly_${today}.csv`;
    }

    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows.map(e => e.join(','))].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    window.dispatchEvent(new CustomEvent('app-notification', { 
        detail: { message: 'REPORT EXPORTED SUCCESSFULLY', type: 'success' } 
    }));
  };

  const SortHeader = ({ label, sortKey, align = 'left' }: { label: string, sortKey: keyof ProductionEntry, align?: 'left' | 'right' | 'center' }) => (
    <th className={`px-8 py-5 cursor-pointer group text-${align}`} onClick={() => handleSort(sortKey)}>
        <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : align === 'center' ? 'justify-center' : ''}`}>
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100' : 'opacity-0 group-hover:opacity-60'}`} />
        </div>
    </th>
  );

  return (
    <div className="space-y-6 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <h2 className="text-2xl font-black text-gray-800 dark:text-white">Production Analytics</h2>

        <div className="flex items-center gap-4">
          <div className="flex items-center bg-white dark:bg-slate-800 rounded-xl p-1.5 border border-gray-200 dark:border-slate-700 shadow-sm">
              <button onClick={() => setViewMode('daily')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black transition ${viewMode === 'daily' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500'}`}><List className="w-4 h-4" /> Daily</button>
              <button onClick={() => setViewMode('monthly')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-black transition ${viewMode === 'monthly' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'text-slate-500'}`}><Calendar className="w-4 h-4" /> Monthly</button>
          </div>

          <button 
            onClick={downloadCSV} 
            className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-emerald-700 transition shadow-lg shadow-emerald-500/20"
          >
            <Download className="w-4 h-4" /> Export Report
          </button>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-3xl p-6 shadow-sm border border-gray-100 dark:border-slate-700 flex flex-wrap gap-6 items-end">
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Date From</label>
          <input type="date" value={dateRange.start} onChange={e => setDateRange(prev => ({...prev, start: e.target.value}))} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold" />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Date To</label>
          <input type="date" value={dateRange.end} onChange={e => setDateRange(prev => ({...prev, end: e.target.value}))} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold" />
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Department</label>
          <select value={category} onChange={e => setCategory(e.target.value)} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold w-full md:w-auto">
            <option value="All">All Departments</option>
            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
        <div className="space-y-2">
          <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest flex items-center gap-1"><Filter className="w-3 h-3" /> Status</label>
          <select value={statusFilter} onChange={e => setStatusFilter(e.target.value)} className="px-4 py-2.5 text-sm bg-gray-50 dark:bg-slate-900 rounded-xl border dark:border-slate-700 outline-none dark:text-white font-bold w-full md:w-auto">
            <option value="All">All Statuses</option>
            <option value="In Progress">In Progress</option>
            <option value="Completed">Completed</option>
          </select>
        </div>
        <button onClick={resetFilters} className="flex items-center gap-1.5 px-4 py-2.5 text-[10px] font-black uppercase text-rose-500 hover:bg-rose-50 rounded-xl transition"><XCircle className="w-4 h-4" /> Reset</button>
      </div>

      <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700">
        <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={viewMode === 'daily' ? chartDailyData : monthlyChartSummaryData} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={isDarkMode ? '#334155' : '#f1f5f9'} />
                    <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 800, fill: '#94a3b8' }} dy={10} />
                    <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fontWeight: 800, fill: '#94a3b8' }} />
                    <Tooltip contentStyle={{ backgroundColor: isDarkMode ? '#1e293b' : '#fff', borderRadius: '16px', border: 'none', fontSize: '12px', fontWeight: 'bold' }} />
                    <Bar dataKey="plan" name="Target Plan" fill="#6366f1" radius={[6, 6, 0, 0]} barSize={viewMode === 'daily' ? 30 : 50} />
                    <Bar dataKey="actual" name="Total Actual" fill="#10b981" radius={[6, 6, 0, 0]} barSize={viewMode === 'daily' ? 30 : 50} />
                    {viewMode === 'monthly' && <Line type="monotone" dataKey="efficiency" name="Eff. %" stroke="#f59e0b" strokeWidth={3} />}
                </ComposedChart>
            </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-slate-700 overflow-hidden">
        <div className="overflow-x-auto custom-scrollbar">
          <table className="w-full text-sm text-left border-collapse">
            <thead className="bg-gray-50/50 dark:bg-slate-900/50 text-slate-400 font-black uppercase text-[10px] tracking-widest border-b dark:border-slate-700">
              {viewMode === 'daily' ? (
                  <tr>
                    <SortHeader label="Date" sortKey="date" />
                    <SortHeader label="Dept" sortKey="category" align="center" />
                    <SortHeader label="Product" sortKey="productName" />
                    <th className="px-8 py-5 text-right">Plan</th>
                    <th className="px-8 py-5 text-right">Actual</th>
                    <th className="px-8 py-5 text-right">Eff. %</th>
                    <SortHeader label="Status" sortKey="status" align="center" />
                  </tr>
              ) : (
                  <tr>
                    <th className="px-8 py-5">Month</th>
                    <th className="px-8 py-5">Process</th>
                    <th className="px-8 py-5 text-right">Plan</th>
                    <th className="px-8 py-5 text-right">Actual</th>
                    <th className="px-8 py-5 text-right">Efficiency %</th>
                  </tr>
              )}
            </thead>
            <tbody className="divide-y divide-gray-50 dark:divide-slate-700/50">
              {viewMode === 'daily' ? (
                  filteredData.map(entry => {
                    const eff = Number(calculateEfficiency(entry.actualQuantity || 0, entry.planQuantity || 0));
                    const isHol = offDays.some(od => od.date === entry.date);
                    const isRest = isWeeklyRestDay(entry.date);
                    return (
                      <tr key={entry.id} className={`hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition-colors ${(isHol || isRest) ? 'bg-amber-50/10' : ''}`}>
                        <td className="px-8 py-6">
                            <div className="font-black text-slate-800 dark:text-white font-mono text-xs">{entry.date}</div>
                            {isHol ? <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-amber-600"><Palmtree className="w-3 h-3" /> Holiday</span> 
                             : isRest ? <span className="flex items-center gap-1.5 text-[9px] font-black uppercase text-indigo-500"><ShieldAlert className="w-3 h-3" /> Rest Day</span>
                             : <span className="text-[9px] font-black uppercase text-slate-300">Operational</span>}
                        </td>
                        <td className="px-8 py-6 text-center">
                          <span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-900 text-slate-500 border dark:border-slate-800">{entry.category}</span>
                        </td>
                        <td className="px-8 py-6"><div className="font-black text-slate-800 dark:text-white">{entry.productName}</div></td>
                        <td className="px-8 py-6 text-right font-black font-mono text-slate-700 dark:text-slate-200">{(entry.planQuantity || 0).toLocaleString()}</td>
                        <td className="px-8 py-6 text-right font-black font-mono text-emerald-500">{(entry.actualQuantity || 0).toLocaleString()}</td>
                        <td className="px-8 py-6 text-right font-black">{eff}%</td>
                        <td className="px-8 py-6 text-center">
                            <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[9px] font-black uppercase border ${entry.status === 'Completed' ? 'bg-emerald-50 text-emerald-600' : 'bg-indigo-50 text-indigo-600'}`}>
                                {entry.status === 'Completed' ? <CheckCircle className="w-3 h-3" /> : <Clock className="w-3 h-3 animate-pulse" />} {entry.status}
                            </div>
                        </td>
                      </tr>
                    );
                  })
              ) : (
                  monthlyData.map(m => (
                      <tr key={`${m.name}-${m.process}`} className="hover:bg-indigo-50/30 dark:hover:bg-indigo-900/10 transition">
                          <td className="px-8 py-6 font-black text-slate-800 dark:text-white text-lg">{m.name}</td>
                          <td className="px-8 py-6"><span className="text-[10px] font-black uppercase px-2.5 py-1 rounded-lg bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 border border-indigo-100">{m.process}</span></td>
                          <td className="px-8 py-6 text-right font-mono font-black text-slate-700 dark:text-slate-200">{(m.plan || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-mono font-black text-emerald-500">{(m.actual || 0).toLocaleString()}</td>
                          <td className="px-8 py-6 text-right font-black"><div className={`inline-flex px-4 py-2 rounded-2xl font-black text-base ${m.efficiency >= 85 ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>{m.efficiency.toFixed(1)}%</div></td>
                      </tr>
                  ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { CATEGORIES, PROCESSES, UNITS } from '../../constants';
import { ProductionEntry, Category, ProcessType, UnitType, ProductionStatus } from '../../types';
import { X, Loader2, AlertTriangle, Palmtree, MessageSquare, ShieldAlert, Ban } from 'lucide-react';
import { getTodayISO, getDbTimestamp } from '../../utils/dateUtils';

interface InputModalProps {
  onClose: () => void;
  editEntry?: ProductionEntry | null;
}

export const InputModal: React.FC<InputModalProps> = ({ onClose, editEntry }) => {
  const { user, hasPermission } = useAuth();
  const { triggerRefresh } = useDashboard();
  const [tab, setTab] = useState<'Plan' | 'Actual'>('Plan');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [date, setDate] = useState(getTodayISO());
  const [category, setCategory] = useState<Category>(CATEGORIES[0]);
  const [process, setProcess] = useState<ProcessType>(PROCESSES[0]);
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [unit, setUnit] = useState<UnitType>('KG');
  const [manpower, setManpower] = useState('0');
  const [batchNo, setBatchNo] = useState('');
  const [planRemark, setPlanRemark] = useState('');
  const [actualRemark, setActualRemark] = useState('');

  const [plans, setPlans] = useState<ProductionEntry[]>([]);
  const [selectedPlanId, setSelectedPlanId] = useState<string>('');

  const offDays = useMemo(() => StorageService.getOffDays(), []);

  const currentOffDay = useMemo(() => {
    const inputDate = (date || '').trim().split(' ')[0];
    return offDays.find(od => (od.date || '').trim().split(' ')[0] === inputDate);
  }, [date, offDays]);

  // Lock logic based on manual off-day entries
  const isLocked = !editEntry && !!currentOffDay;

  const availableProcesses = useMemo(() => {
    if (['Toothpaste', 'Rocksalt', 'Cosmetic'].includes(category)) {
      return PROCESSES.filter(p => p !== 'Encapsulation');
    }
    return [...PROCESSES];
  }, [category]);

  const inputClasses = "w-full p-2.5 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 text-slate-900 dark:text-white font-bold focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 outline-none transition-all shadow-sm";

  useEffect(() => {
    if (!availableProcesses.includes(process)) {
      setProcess(availableProcesses[0]);
    }
  }, [category, availableProcesses, process]);

  useEffect(() => {
    if (editEntry) {
      setDate((editEntry.date || '').trim().split(' ')[0]);
      setCategory(editEntry.category);
      setProcess(editEntry.process);
      setProductName(editEntry.productName);
      setUnit(editEntry.unit || 'KG');

      if (editEntry.actualQuantity > 0) {
        setTab('Actual');
        setQuantity(editEntry.actualQuantity.toString());
      } else {
        setTab('Plan');
        setQuantity(editEntry.planQuantity.toString());
      }

      setManpower(editEntry.manpower ? Number(editEntry.manpower).toString() : '0');
      setBatchNo(editEntry.batchNo || '');
      setPlanRemark(editEntry.planRemark || '');
      setActualRemark(editEntry.actualRemark || '');
    } else {
      if (user?.role === 'operator') setTab('Actual');
      else if (user?.role === 'planner') setTab('Plan');
    }
  }, [editEntry, user]);

  useEffect(() => {
    if (tab === 'Actual' && !editEntry) {
        const all = StorageService.getProductionData();
        const normalizedInputDate = (date || '').trim().split(' ')[0];
        const relevant = all.filter(p => (p.date || '').trim().split(' ')[0] === normalizedInputDate);
        setPlans(relevant);
        setSelectedPlanId('');
    }
  }, [date, tab, editEntry]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isLocked) return;

    setIsSubmitting(true);
    const normalizedDate = (date || '').trim().split(' ')[0];
    const currentData = StorageService.getProductionData();
    const determinedStatus: ProductionStatus = tab === 'Actual' ? 'Completed' : 'In Progress';

    try {
        if (editEntry) {
            const updated = currentData.map(p => {
                if (p.id === editEntry.id) {
                    const newQty = parseInt(quantity || '0');
                    return { 
                        ...p, 
                        date: normalizedDate, 
                        category, process, productName, unit,
                        planQuantity: tab === 'Plan' ? newQty : p.planQuantity,
                        actualQuantity: tab === 'Actual' ? newQty : p.actualQuantity,
                        batchNo, manpower: parseFloat(manpower || '0'),
                        planRemark,
                        actualRemark,
                        status: (tab === 'Actual' && newQty > 0 ? 'Completed' : p.status) as ProductionStatus,
                        lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                    } as ProductionEntry;
                }
                return p;
            });
            StorageService.saveProductionData(updated);
        } else {
            if (tab === 'Plan') {
                const newEntry: ProductionEntry = {
                    id: Date.now().toString(),
                    date: normalizedDate, 
                    category, process, productName, unit,
                    planQuantity: parseInt(quantity || '0'), actualQuantity: 0,
                    planRemark,
                    actualRemark: '',
                    status: 'In Progress',
                    lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                };
                StorageService.saveProductionData([...currentData, newEntry]);
            } else {
                if (!selectedPlanId) throw new Error("Please select a plan");
                const updated = currentData.map(p => {
                    if (p.id === selectedPlanId) {
                        return { 
                            ...p, 
                            actualQuantity: parseInt(quantity || '0'), 
                            unit, batchNo, manpower: parseFloat(manpower || '0'),
                            actualRemark, status: 'Completed' as ProductionStatus,
                            lastUpdatedBy: user!.id, updatedAt: getDbTimestamp()
                        } as ProductionEntry;
                    }
                    return p;
                });
                StorageService.saveProductionData(updated);
            }
        }

        window.dispatchEvent(new CustomEvent('app-notification', { 
            detail: { message: determinedStatus === 'Completed' ? 'PRODUCTION COMPLETED' : 'PLAN SAVED', type: 'success' } 
        }));
        triggerRefresh();
        onClose();
    } catch (err: any) {
        window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'Operation failed', type: 'info' } }));
    } finally {
        setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-800 rounded-2xl w-full max-w-2xl shadow-2xl overflow-hidden border border-slate-200 dark:border-slate-700 relative max-h-[90vh] flex flex-col">
        {isSubmitting && (
            <div className="absolute inset-0 bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm z-[60] flex flex-col items-center justify-center">
                <Loader2 className="w-10 h-10 text-indigo-600 animate-spin mb-2" />
                <p className="text-xs font-black uppercase tracking-widest text-indigo-600">Uploading to Cloud...</p>
            </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-slate-700 shrink-0">
            {!editEntry ? (
              <>
                {hasPermission(['admin', 'manager', 'planner']) && (
                    <button onClick={() => setTab('Plan')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        1. Production Plan
                    </button>
                )}
                {hasPermission(['admin', 'manager', 'operator']) && (
                    <button onClick={() => setTab('Actual')} 
                        className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest text-center transition border-b-2 ${tab === 'Actual' ? 'border-emerald-50 text-emerald-600' : 'border-transparent text-slate-400 hover:text-slate-600'}`}>
                        2. Record Actual
                    </button>
                )}
              </>
            ) : (
              <div className="flex-1 flex overflow-hidden">
                <button onClick={() => setTab('Plan')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Plan' ? 'border-indigo-600 text-indigo-600 bg-indigo-50/10' : 'border-transparent text-slate-400'}`}>
                    Plan Details
                </button>
                <button onClick={() => setTab('Actual')} className={`flex-1 py-4 font-black text-[11px] uppercase tracking-widest transition border-b-2 ${tab === 'Actual' ? 'border-emerald-50 text-emerald-600 bg-emerald-50/10' : 'border-transparent text-slate-400'}`}>
                    Actual Results
                </button>
              </div>
            )}
        </div>

        <div className="p-6 relative overflow-y-auto custom-scrollbar flex-1">
            <button onClick={onClose} className="absolute top-2 right-4 text-slate-300 hover:text-rose-500 transition-colors z-20"><X className="w-5 h-5" /></button>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Production Date</label>
                    <input type="date" required value={date} onChange={e => setDate(e.target.value)} className={inputClasses} />

                    {currentOffDay && (
                      <div className={`mt-3 p-3 border rounded-xl flex items-center gap-3 shadow-sm ${
                        currentOffDay.type === 'Public Holiday' ? 'bg-rose-50 dark:bg-rose-900/20 border-rose-200 dark:border-rose-800' :
                        currentOffDay.type === 'Rest Day' ? 'bg-indigo-50 dark:bg-indigo-900/20 border-indigo-200 dark:border-indigo-800' :
                        'bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-800'
                      }`}>
                        <div className={`p-2 rounded-lg text-white ${
                            currentOffDay.type === 'Public Holiday' ? 'bg-rose-500' :
                            currentOffDay.type === 'Rest Day' ? 'bg-indigo-500' :
                            'bg-amber-500'
                        }`}>
                          <Ban className="w-4 h-4" />
                        </div>
                        <div className="flex-1">
                          <p className={`text-[10px] font-black uppercase tracking-widest leading-none mb-1 ${
                                currentOffDay.type === 'Public Holiday' ? 'text-rose-600 dark:text-rose-400' :
                                currentOffDay.type === 'Rest Day' ? 'text-indigo-600 dark:text-indigo-400' :
                                'text-amber-600 dark:text-amber-400'
                          }`}>{currentOffDay.type}</p>
                          <p className="text-xs font-black text-slate-900 dark:text-white leading-tight">{currentOffDay.description}</p>
                        </div>
                      </div>
                    )}
                </div>

                {tab === 'Plan' ? (
                    <>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Category</label>
                                <select value={category} onChange={e => setCategory(e.target.value as Category)} className={inputClasses}>
                                    {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                                </select>
                            </div>
                            <div>
                                <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Process</label>
                                <select value={process} onChange={e => setProcess(e.target.value as ProcessType)} className={inputClasses}>
                                    {availableProcesses.map(p => <option key={p} value={p}>{p}</option>)}
                                </select>
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1">Product Name</label>
                            <input type="text" required value={productName} onChange={e => setProductName(e.target.value.toUpperCase())} className={inputClasses} placeholder="Enter product name..." />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div className="flex-1">
