    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(seed));
  }
  if (!localStorage.getItem(KEYS.LOGS)) {
    localStorage.setItem(KEYS.LOGS, JSON.stringify([]));
  }
};

init();

