      process: String(data[3] || 'Mixing') as any,
      productName: String(data[4] || 'Unknown'),
      planQuantity: Number(data[5] || 0),
      actualQuantity: Number(data[6] || 0),
      unit: normalizeUnit(data[7]), // Column H
      batchNo: String(data[8] || ''),
      manpower: Number(data[9] || 0),
      lastUpdatedBy: String(data[10] || ''),
      updatedAt: String(data[11] || getDbTimestamp()),
      remark: String(data[12] || ''),
      planRemark: String(data[13] || ''),
      actualRemark: String(data[14] || ''),
      status: (data[15] as ProductionStatus) || (Number(data[6] || 0) >= Number(data[5] || 1) ? 'Completed' : 'In Progress')
    };
  } else {
    // If data comes from LocalStorage as an object
    entry = {
      ...data,
      id: String(data.id || Date.now()),
      date: String(data.date || '').split(' ')[0],
      productName: String(data.productName || 'Unknown'),
      planQuantity: Number(data.planQuantity || 0),
      actualQuantity: Number(data.actualQuantity || 0),
      unit: normalizeUnit(data.unit),
      manpower: Number(data.manpower || 0),
      batchNo: String(data.batchNo || ''),
      remark: String(data.remark || ''),
      planRemark: String(data.planRemark || ''),
      actualRemark: String(data.actualRemark || ''),
      process: String(data.process || 'Mixing') as any,
      category: String(data.category || 'Healthcare') as any,
      status: data.status || (Number(data.actualQuantity || 0) >= Number(data.planQuantity || 1) ? 'Completed' : 'In Progress'),
      updatedAt: String(data.updatedAt || getDbTimestamp())
    };
  }
  return entry as ProductionEntry;
};

// Normalizer for Activity Logs
const normalizeLog = (data: any): ActivityLog => {
  if (!data) return {} as ActivityLog;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      timestamp: String(data[1] || getDbTimestamp()),
      userId: String(data[2] || ''),
      userName: String(data[3] || 'System'),
      action: String(data[4] || 'LOG'),
      details: String(data[5] || '')
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now()),
    timestamp: String(data.timestamp || getDbTimestamp()),
    userName: String(data.userName || 'Unknown'),
    details: String(data.details || '')
  };
};

// Normalizer for Off Days
const normalizeOffDay = (data: any): OffDay => {
  if (!data) return {} as OffDay;

  if (Array.isArray(data)) {
    return {
      id: String(data[0] || Date.now()),
      date: String(data[1] || '').split(' ')[0],
      description: String(data[2] || 'Holiday'),
      createdBy: String(data[3] || 'System'),
      type: (data[4] as OffDayType) || 'Off Day'
    };
  }
  return {
    ...data,
    id: String(data.id || Date.now()),
    date: String(data.date || '').split(' ')[0],
    description: String(data.description || 'Holiday'),
    type: (data.type as OffDayType) || 'Off Day'
  };
};

const init = () => {
  if (!localStorage.getItem(KEYS.USERS)) {
    localStorage.setItem(KEYS.USERS, JSON.stringify(INITIAL_USERS));
  }
  if (!localStorage.getItem(KEYS.OFF_DAYS)) {
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(INITIAL_OFF_DAYS));
  }
  if (!localStorage.getItem(KEYS.PRODUCTION)) {
    // START FIX: Remove dummy data seeding
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify([]));
    // END FIX
  }
  if (!localStorage.getItem(KEYS.LOGS)) {
    localStorage.setItem(KEYS.LOGS, JSON.stringify([]));
  }
};

init();

export const StorageService = {
  getUsers: (): User[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.USERS) || '[]');
      return Array.isArray(data) ? data : [];
    } catch { return []; }
  },
  saveUsers: (users: User[]) => {
    localStorage.setItem(KEYS.USERS, JSON.stringify(users));
    GoogleSheetsService.saveData('saveUsers', users);
  },

  getProductionData: (): ProductionEntry[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.PRODUCTION) || '[]');
      return Array.isArray(data) ? data.map(normalizeProduction).filter((p: ProductionEntry) => p.date && p.date.length > 0) : [];
    } catch { return []; }
  },
  saveProductionData: (data: ProductionEntry[]) => {
    const cleaned = data.map(normalizeProduction).filter((p: ProductionEntry) => p.date && p.date.length > 0);
    localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(cleaned));
    GoogleSheetsService.saveData('saveProduction', cleaned);
  },

  deleteProductionEntry: (id: string): { updatedData: ProductionEntry[], deletedItem: ProductionEntry | null } => {
    try {
      const data = StorageService.getProductionData();
      const targetId = String(id);
      const targetItem = data.find((p: ProductionEntry) => String(p.id) === targetId) || null;
      const updatedData = data.filter((p: ProductionEntry) => String(p.id) !== targetId);
      StorageService.saveProductionData(updatedData);
      return { updatedData, deletedItem: targetId ? targetItem : null };
    } catch (err) {
      console.error("Storage delete error:", err);
      return { updatedData: StorageService.getProductionData(), deletedItem: null };
    }
  },

  getOffDays: (): OffDay[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.OFF_DAYS) || '[]');
      return Array.isArray(data) ? data.map(normalizeOffDay).filter((od: OffDay) => od.date && od.date.length > 0) : [];
    } catch { return []; }
  },
  saveOffDays: (days: OffDay[]) => {
    const cleaned = days.map(normalizeOffDay).filter((od: OffDay) => od.date && od.date.length > 0);
    localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(cleaned));
    GoogleSheetsService.saveData('saveOffDays', cleaned);
  },

  syncWithSheets: async () => {
    if (!GoogleSheetsService.isEnabled()) return;

    try {
      const results = await Promise.all([
        GoogleSheetsService.fetchData<any[]>('getProduction'),
        GoogleSheetsService.fetchData<any[]>('getOffDays'),
        GoogleSheetsService.fetchData<any[]>('getLogs'),
        GoogleSheetsService.fetchData<User[]>('getUsers')
      ]);

      if (results[0] && Array.isArray(results[0])) {
          const cleaned = results[0].map(normalizeProduction).filter((p: ProductionEntry) => p.date && p.date.length > 0);
          localStorage.setItem(KEYS.PRODUCTION, JSON.stringify(cleaned));
      }

      if (results[1] && Array.isArray(results[1])) {
          const cleaned = results[1].map(normalizeOffDay).filter((od: OffDay) => od.date && od.date.length > 0);
          localStorage.setItem(KEYS.OFF_DAYS, JSON.stringify(cleaned));
      }

      if (results[2] && Array.isArray(results[2])) {
          const cleanedLogs = results[2].map(normalizeLog).filter((l: ActivityLog) => l.timestamp);
          localStorage.setItem(KEYS.LOGS, JSON.stringify(cleanedLogs));
      }

      if (results[3] && Array.isArray(results[3])) {
          localStorage.setItem(KEYS.USERS, JSON.stringify(results[3]));
      }
    } catch (err) {
      console.error("Critical Sync Failure:", err);
      throw err;
    }
  },

  getLogs: (): ActivityLog[] => {
    try {
      const data = JSON.parse(localStorage.getItem(KEYS.LOGS) || '[]');
      return Array.isArray(data) ? data.map(normalizeLog) : [];
    } catch { return []; }
  },
  addLog: (log: Omit<ActivityLog, 'id' | 'timestamp'>) => {
    try {
      const logs = StorageService.getLogs();
      const newLog: ActivityLog = {
        ...log,
        id: Date.now().toString(),
        timestamp: getDbTimestamp(),
      };
      logs.unshift(newLog);
      if (logs.length > 500) logs.pop(); 

      localStorage.setItem(KEYS.LOGS, JSON.stringify(logs));
      GoogleSheetsService.saveData('saveLogs', logs);
    } catch (err) {
      console.error("Logging error:", err);
    }
  },

  getSession: (): User | null => {
    try {
      const session = localStorage.getItem(KEYS.CURRENT_USER);
      return session ? JSON.parse(session) : null;
    } catch { return null; }
  },
  setSession: (user: User | null) => {
    if (user) localStorage.setItem(KEYS.CURRENT_USER, JSON.stringify(user));
    else localStorage.removeItem(KEYS.CURRENT_USER);
  }
};

import React, { useMemo, useState } from 'react';
import { useDashboard } from '../../contexts/DashboardContext';
import { StorageService } from '../../services/storageService';
import { ProductionEntry, OffDay, ProductionStatus } from '../../types';
import { PROCESSES } from '../../constants';
import { 
  ClipboardList, List, Calendar, 
  Download, Pencil, Trash2, Layers,
  Palmtree, MessageSquare, ArrowUpDown, Clock, CheckCircle, ShieldAlert, Coffee, Ban
} from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { formatDisplayDate, getCurrentMonthISO } from '../../utils/dateUtils';

type SortConfig = {
    key: keyof ProductionEntry;
    direction: 'asc' | 'desc';
} | null;

export const Dashboard: React.FC = () => {
  const { category, refreshKey, triggerRefresh } = useDashboard();
  const { user, hasPermission } = useAuth();

  const [selectedMonth, setSelectedMonth] = useState<string>(getCurrentMonthISO());
  const [sortConfig, setSortConfig] = useState<SortConfig>(null);

  const { productionData, offDays } = useMemo(() => {
    return {
      productionData: StorageService.getProductionData(),
      offDays: StorageService.getOffDays(),
    };
  }, [refreshKey]);

  const handleSort = (key: keyof ProductionEntry) => {
    let direction: 'asc' | 'desc' = 'asc';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'asc') {
        direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  const dashboardData = useMemo(() => {
    const relevant = productionData.filter(d => d && d.category === category && d.date);
    let selectedMonthPlan = 0;
    let selectedMonthActual = 0;
    const selectedMonthProcessMap = new Map<string, {process: string, Plan: number, Actual: number}>();
    const validProcesses = ['Toothpaste', 'Rocksalt', 'Cosmetic'].includes(category)
      ? PROCESSES.filter(p => p !== 'Encapsulation')
      : [...PROCESSES];

    validProcesses.forEach(proc => {
      selectedMonthProcessMap.set(proc, { process: proc, Plan: 0, Actual: 0 });
    });

    relevant.forEach(d => {
      const dateStr = (d.date || '').trim().substring(0, 7);
      if (dateStr === selectedMonth) {
        selectedMonthPlan += (d.planQuantity || 0);
        selectedMonthActual += (d.actualQuantity || 0);
        const procName = d.process || 'Other';
        if (selectedMonthProcessMap.has(procName)) {
          const p = selectedMonthProcessMap.get(procName)!;
          p.Plan += (d.planQuantity || 0);
          p.Actual += (d.actualQuantity || 0);
        }
      }
    });

    return {
      filteredData: relevant.sort((a,b) => (b.date || '').localeCompare(a.date || '')),
      selectedMonthStats: { 
        plan: selectedMonthPlan, 
        actual: selectedMonthActual,
        efficiency: selectedMonthPlan > 0 ? (selectedMonthActual / selectedMonthPlan) * 100 : 0
      },
      chartData: Array.from(selectedMonthProcessMap.values())
    };
  }, [productionData, category, selectedMonth]);

  const dailyGroups = useMemo(() => {
    const baseData = dashboardData.filteredData;
    const filteredEntries = baseData.filter(d => d && d.date && d.date.trim().startsWith(selectedMonth));
    const dates = new Set<string>();

    // START FIX: Only gather dates that have entries or are off days
    filteredEntries.forEach(e => {
        if (e.date) dates.add(e.date.trim().substring(0, 10));
    });

    offDays.forEach(od => {
        if (od.date && od.date.trim().startsWith(selectedMonth)) {
            dates.add(od.date.trim().substring(0, 10));
        }
    });
    // END FIX

    const sortedDates = Array.from(dates).sort((a, b) => (b || '').localeCompare(a || ''));
    const statusWeight: Record<string, number> = { 'In Progress': 1, 'Completed': 2 };

    return sortedDates.map(dateKey => {
        let entriesForDate = filteredEntries.filter(d => d.date && d.date.trim().substring(0, 10) === dateKey);

        if (sortConfig) {
            entriesForDate = [...entriesForDate].sort((a, b) => {
                let aValue: any = a[sortConfig.key];
                let bValue: any = b[sortConfig.key];
                if (sortConfig.key === 'status') {
                    aValue = statusWeight[a.status as ProductionStatus] || 0;
                    bValue = statusWeight[b.status as ProductionStatus] || 0;
                }
                if (aValue < bValue) return sortConfig.direction === 'asc' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'asc' ? 1 : -1;
                return 0;
            });
        }

        const offDayInfo = offDays.find(od => od.date && od.date.trim().substring(0, 10) === dateKey);
        const totalActualForDate = entriesForDate.reduce((sum, entry) => sum + (entry.actualQuantity || 0), 0);

        return {
            date: dateKey,
            totalActualForDate,
            entries: entriesForDate,
            offDay: offDayInfo
        };
    });
  }, [dashboardData.filteredData, offDays, selectedMonth, sortConfig]);

  const handleDelete = (id: string) => {
      if(!window.confirm("PERMANENTLY delete record?")) return;
      const { deletedItem } = StorageService.deleteProductionEntry(id);
      if (deletedItem) {
          StorageService.addLog({
            userId: user!.id, userName: user!.name, action: 'DELETE_RECORD',
            details: `Deleted: ${deletedItem.productName} (${deletedItem.date})`
          });
          window.dispatchEvent(new CustomEvent('app-notification', { detail: { message: 'RECORD DELETED', type: 'info' } }));
      }
      triggerRefresh();
  };

  const handleEdit = (entry: ProductionEntry) => {
    window.dispatchEvent(new CustomEvent('edit-production-entry', { detail: entry }));
  };

  const getOffDayIcon = (type: string) => {
    switch(type) {
      case 'Public Holiday': return <Palmtree className="w-6 h-6 text-rose-500" />;
      case 'Rest Day': return <Coffee className="w-6 h-6 text-indigo-500" />;
      case 'Off Day': return <Ban className="w-6 h-6 text-amber-500" />;
      default: return <Calendar className="w-6 h-6 text-slate-400" />;
    }
  };

  const getOffDayBadgeStyle = (type: string) => {
    switch(type) {
      case 'Public Holiday': return 'bg-rose-500 text-white shadow-rose-500/20';
      case 'Rest Day': return 'bg-indigo-500 text-white shadow-indigo-500/20';
      case 'Off Day': return 'bg-amber-500 text-white shadow-amber-500/20';
      default: return 'bg-slate-400 text-white';
    }
  };

  const SortHeader = ({ label, sortKey }: { label: string, sortKey: keyof ProductionEntry }) => (
    <th className="px-8 py-4 cursor-pointer group" onClick={() => handleSort(sortKey)}>
        <div className="flex items-center gap-1">
            <span className={sortConfig?.key === sortKey ? 'text-indigo-600' : ''}>{label}</span>
            <ArrowUpDown className={`w-3 h-3 transition-opacity ${sortConfig?.key === sortKey ? 'opacity-100' : 'opacity-0 group-hover:opacity-40'}`} />
        </div>
  );

  return (
    <div className="space-y-8 pb-12">
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-2">
            <Layers className="w-4 h-4 text-indigo-500" />
            <h3 className="text-[12px] font-black text-slate-400 uppercase tracking-[0.3em]">Monthly Process Breakdown</h3>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            {dashboardData.chartData.map((item) => {
                const eff = item.Plan > 0 ? (item.Actual / item.Plan) * 100 : 0;
                return (
                    <div key={item.process} className="glass-panel p-8 rounded-[2.5rem] border border-gray-100 dark:border-slate-800 shadow-sm group hover:border-indigo-500/30 transition-all duration-300">
                        <div className="flex items-center justify-between mb-6">
                          <p className="text-sm font-black text-indigo-600 dark:text-indigo-400 uppercase tracking-widest">{item.process}</p>
                          <div className="w-2 h-2 rounded-full bg-indigo-500 animate-pulse" />
                        </div>
                        <div className="space-y-5">
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Plan</span>
                                <span className="text-2xl font-black text-slate-800 dark:text-white font-mono">{(item.Plan || 0).toLocaleString()}</span>
                            </div>
                            <div className="flex flex-col gap-1">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Actual</span>
                                <span className="text-2xl font-black text-emerald-500 font-mono">{(item.Actual || 0).toLocaleString()}</span>
                            </div>
                            <div className="pt-5 border-t border-gray-50 dark:border-slate-700 flex justify-between items-center">
                                <span className="text-[11px] font-black text-slate-400 uppercase">Efficiency</span>
                                <span className={`text-xl font-black font-mono ${eff >= 100 ? 'text-emerald-500' : eff >= 75 ? 'text-amber-500' : 'text-rose-500'}`}>
                                    {(eff || 0).toFixed(1)}%
                                </span>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex flex-col md:flex-row justify-between items-end gap-4 px-2">
            <div>
               <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center gap-2">
                  <List className="w-5 h-5 text-indigo-500" />
                  Daily Production Log
               </h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">{selectedMonth} Operational granularity</p>
            </div>
            <input type="month" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)} className="px-4 py-2 text-sm font-bold bg-white dark:bg-slate-800 rounded-xl shadow-sm border border-gray-100 dark:border-slate-700 dark:text-white outline-none" />
        </div>

        <div className="space-y-6">
            {dailyGroups.length === 0 ? (
