export const generateSeedProductionData = (): ProductionEntry[] => {
  const data: ProductionEntry[] = [];
  const products = ['Pain Relief Gel', 'Minty Fresh', 'Pink Salt Fine', 'Vitamin C', 'Charcoal Paste', 'Herbal Shampoo', 'Skin Repair Cream'];

  const todayStr = getTodayISO();
  const [y, m, d] = todayStr.split('-').map(Number);
  const baseDate = new Date(y, m - 1, d);

  for (let i = 0; i < 30; i++) {
    const d = new Date(baseDate);
    d.setDate(baseDate.getDate() - i);

    const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

    // Note: WEEKLY_OFF_DAYS is empty, so this will no longer skip any days
    if (WEEKLY_OFF_DAYS.includes(d.getDay())) continue;

    products.forEach((prod, idx) => {
      if (Math.random() > 0.8) return;

      const plan = Math.floor(Math.random() * 500) + 500;
      const actual = Math.floor(plan * (0.8 + Math.random() * 0.2));

      data.push({
        id: `seed-${i}-${idx}`,
        date: dateStr,
        category: CATEGORIES[idx % CATEGORIES.length],
        process: PROCESSES[idx % PROCESSES.length],
        productName: prod,
        planQuantity: plan,
        actualQuantity: actual,
        unit: UNITS[idx % UNITS.length],
        batchNo: `B-${dateStr.replace(/-/g, '')}-${idx}`,
        manpower: Math.floor(Math.random() * 5) + 3.5,
        planRemark: 'Standard monthly batch',
        actualRemark: actual < plan ? 'Machine maintenance slowdown' : 'Optimal output achieved',
        status: actual >= plan ? 'Completed' : 'In Progress',
        lastUpdatedBy: 'u1',
        updatedAt: getDbTimestamp()
      });
    });
  }
  return data;
};

/**
 * HALAGEL DATE UTILITIES
 * Strictly enforces Malaysia Time (UTC+8) to prevent the "Yesterday Bug".
 */

/**
 * Returns YYYY-MM-DD based on Malaysia Timezone.
 * Safe for use in <input type="date">
 */
export const getTodayISO = (): string => {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kuala_Lumpur',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(new Date());
};

/**
 * Checks if a given date string is a weekly rest day.
 * Updated to always return false as the company operates 7 days a week.
 */
export const isWeeklyRestDay = (dateStr: string): boolean => {
  return false;
};

/**
 * Returns YYYY-MM based on Malaysia Timezone.
 */
export const getCurrentMonthISO = (): string => {
  return getTodayISO().substring(0, 7);
};

/**
 * Returns the current date and time in the format YYYY-MM-DD HH:mm:ss
 * tailored for database/sheet storage.
 */
export const getDbTimestamp = (): string => {
  const now = new Date();
  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kuala_Lumpur',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  });

  const parts = formatter.formatToParts(now);
  const find = (type: string) => parts.find(p => p.type === type)?.value;

  return `${find('year')}-${find('month')}-${find('day')} ${find('hour')}:${find('minute')}:${find('second')}`;
};

/**
 * Formats ISO or DB timestamp string to YYYY-MM-DD HH:mm:ss in Malaysia Time.
 */
export const formatFullTimestamp = (isoStr: string): string => {
  if (!isoStr) return '';

  // If already in DB format, return as is
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(isoStr)) {
    return isoStr;
  }

  const date = new Date(isoStr);
  if (isNaN(date.getTime())) return isoStr;

  const formatter = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kuala_Lumpur',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  });

  const parts = formatter.formatToParts(date);
  const find = (type: string) => parts.find(p => p.type === type)?.value;

  return `${find('year')}-${find('month')}-${find('day')} ${find('hour')}:${find('minute')}:${find('second')}`;
};

/**
 * Formats YYYY-MM-DD for display (e.g., "2025-12-28 SUNDAY").
 */
export const formatDisplayDate = (dateStr: string): string => {
  if (!dateStr) return 'Invalid Date';

  const cleanDate = dateStr.split(' ')[0].split('T')[0];
  const parts = cleanDate.split('-');

  if (parts.length !== 3) return cleanDate;

  const year = parseInt(parts[0], 10);
  const month = parseInt(parts[1], 10);
  const day = parseInt(parts[2], 10);

  const localDate = new Date(year, month - 1, day, 12, 0, 0);

  if (isNaN(localDate.getTime())) return cleanDate;

  const dayName = new Intl.DateTimeFormat('en-MY', { 
    weekday: 'long', 
    timeZone: 'Asia/Kuala_Lumpur' 
  }).format(localDate).toUpperCase();

  return `${cleanDate} ${dayName}`;
};

/**
 * Validates if a string is a valid YYYY-MM-DD format
 */
export const isValidISODate = (dateStr: string): boolean => {
  return /^\d{4}-\d{2}-\d{2}$/.test(dateStr);
};

